/**
 * app.js — acme-rules Rule Engine
 *
 * POST /check evaluates a structured rule against a caller-supplied context.
 *
 * NOTE ON SECURITY — why the docs/RULES_ENGINE.md reference is NOT used
 * -----------------------------------------------------------------------
 * The reference implementation in RULES_ENGINE.md builds a runtime function
 * from a raw caller-supplied string:
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * Accepting arbitrary JavaScript from an HTTP request and executing it with
 * new Function() (or eval()) grants every caller full server-side code
 * execution with the privileges of the Node process — identical to RCE.
 * An attacker can read environment variables and secrets, traverse the file
 * system, spawn child processes, exfiltrate data to external hosts, or simply
 * crash the server. This is a critical vulnerability regardless of whether the
 * service is internal or external.
 *
 * The safe replacement below evaluates a *structured* rule object instead of
 * a free-form string, supporting the same practical use-cases (field
 * comparisons and boolean logic) without executing untrusted code.
 */

"use strict";

const express = require("express");

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Supported comparison operators.
 * All comparisons are performed between a context field value and a literal.
 */
const COMPARISON_OPS = {
  eq:  (a, b) => a === b,
  neq: (a, b) => a !== b,
  gt:  (a, b) => a >   b,
  gte: (a, b) => a >=  b,
  lt:  (a, b) => a <   b,
  lte: (a, b) => a <=  b,
};

/**
 * Resolve a dot-separated field path against an object.
 * e.g. getField({ user: { age: 30 } }, "user.age") => 30
 *
 * @param {Record<string, unknown>} ctx
 * @param {string} field
 * @returns {unknown}
 */
function getField(ctx, field) {
  return String(field)
    .split(".")
    .reduce((obj, key) => (obj != null ? obj[key] : undefined), ctx);
}

/**
 * Evaluate a single comparison node:
 *   { "field": "amount", "op": "gt", "value": 100 }
 *
 * @param {Record<string, unknown>} ctx
 * @param {{ field: string, op: string, value: unknown }} node
 * @returns {boolean}
 */
function evalComparison(ctx, node) {
  const { field, op, value } = node;

  if (typeof field !== "string" || field.trim() === "") {
    throw new Error('Rule comparison requires a non-empty string "field".');
  }
  if (!(op in COMPARISON_OPS)) {
    throw new Error(
      `Unknown operator "${op}". Allowed: ${Object.keys(COMPARISON_OPS).join(", ")}.`
    );
  }

  const actual = getField(ctx, field);
  return COMPARISON_OPS[op](actual, value);
}

/**
 * Recursively evaluate a rule node against a context object.
 *
 * Supported node shapes
 * ─────────────────────
 * Comparison  — { field, op, value }
 * AND         — { and: [ <node>, … ] }
 * OR          — { or:  [ <node>, … ] }
 * NOT         — { not: <node> }
 *
 * @param {Record<string, unknown>} ctx
 * @param {unknown} node
 * @returns {boolean}
 */
function evalRule(ctx, node) {
  if (node === null || typeof node !== "object" || Array.isArray(node)) {
    throw new Error("Each rule node must be a plain object.");
  }

  // Boolean combinators
  if ("and" in node) {
    if (!Array.isArray(node.and) || node.and.length === 0) {
      throw new Error('"and" must be a non-empty array of rule nodes.');
    }
    return node.and.every((child) => evalRule(ctx, child));
  }

  if ("or" in node) {
    if (!Array.isArray(node.or) || node.or.length === 0) {
      throw new Error('"or" must be a non-empty array of rule nodes.');
    }
    return node.or.some((child) => evalRule(ctx, child));
  }

  if ("not" in node) {
    return !evalRule(ctx, node.not);
  }

  // Leaf comparison node
  if ("field" in node) {
    return evalComparison(ctx, node);
  }

  throw new Error(
    'Rule node must contain one of: "field" (comparison), "and", "or", or "not".'
  );
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * Request body shape:
 * {
 *   "rule":    { … },          // structured rule node (required)
 *   "context": { … }           // arbitrary key/value data to evaluate against (required)
 * }
 *
 * Success response (200):
 * { "result": true | false }
 *
 * Error response (400):
 * { "error": "<message>" }
 */
app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined || rule === null) {
    return res.status(400).json({ error: '"rule" is required.' });
  }
  if (context === undefined || context === null || typeof context !== "object" || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" must be a plain object.' });
  }

  try {
    const result = evalRule(context, rule);
    return res.status(200).json({ result });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // export for testing

