/**
 * app.js — acme-rules Rule Engine API
 *
 * POST /check
 *   Body: { "rule": "<expression>", "context": { ...fields } }
 *   Returns: { "result": true|false }
 *
 * Rule expressions are evaluated by a safe, sandboxed AST evaluator
 * (see evalRule / parseExpr below).  The server never calls eval() or
 * new Function() with caller-supplied strings; doing so would allow
 * Remote Code Execution against the server process.
 */

'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
// Supports a subset of JavaScript expressions sufficient for data-comparison
// rules such as those documented in RULES_ENGINE.md:
//
//   ctx.amount > 100
//   ctx.role === 'admin'
//   ctx.age >= 18 && ctx.country !== 'US'
//   ctx.score > 50 || ctx.vip === true
//   !ctx.banned
//   ctx.tags.includes('premium')
//
// Supported grammar (recursive descent):
//   expr        → or
//   or          → and  ( '||' and )*
//   and         → not  ( '&&' not )*
//   not         → '!' not  |  comparison
//   comparison  → call  ( ( '===' | '!==' | '>=' | '<=' | '>' | '<' ) call )*
//   call        → primary ( '.' IDENT '(' argList ')' )*
//   primary     → NUMBER | STRING | BOOLEAN | NULL
//               | '(' expr ')'
//               | IDENT ( '.' IDENT )*          ← field path into ctx
//   argList     → ( expr ( ',' expr )* )?
// ---------------------------------------------------------------------------

/**
 * Tokenise `src` into an array of tokens.
 * Each token: { type, value }
 * Types: NUMBER, STRING, BOOLEAN, NULL, IDENT, OP, LPAREN, RPAREN, COMMA, DOT
 *
 * Throws a descriptive SyntaxError for unrecognised characters so callers
 * cannot probe server internals through error messages.
 */
function tokenize(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Multi-char operators first
    if (src.startsWith('===', i)) { tokens.push({ type: 'OP', value: '===' }); i += 3; continue; }
    if (src.startsWith('!==', i)) { tokens.push({ type: 'OP', value: '!==' }); i += 3; continue; }
    if (src.startsWith('&&',  i)) { tokens.push({ type: 'OP', value: '&&'  }); i += 2; continue; }
    if (src.startsWith('||',  i)) { tokens.push({ type: 'OP', value: '||'  }); i += 2; continue; }
    if (src.startsWith('>=',  i)) { tokens.push({ type: 'OP', value: '>='  }); i += 2; continue; }
    if (src.startsWith('<=',  i)) { tokens.push({ type: 'OP', value: '<='  }); i += 2; continue; }

    // Single-char tokens
    if (src[i] === '>') { tokens.push({ type: 'OP',     value: '>'  }); i++; continue; }
    if (src[i] === '<') { tokens.push({ type: 'OP',     value: '<'  }); i++; continue; }
    if (src[i] === '!') { tokens.push({ type: 'OP',     value: '!'  }); i++; continue; }
    if (src[i] === '(') { tokens.push({ type: 'LPAREN', value: '('  }); i++; continue; }
    if (src[i] === ')') { tokens.push({ type: 'RPAREN', value: ')'  }); i++; continue; }
    if (src[i] === ',') { tokens.push({ type: 'COMMA',  value: ','  }); i++; continue; }
    if (src[i] === '.') { tokens.push({ type: 'DOT',    value: '.'  }); i++; continue; }

    // Number literal  (integer or decimal, no leading sign — use comparison for negation)
    if (/[0-9]/.test(src[i])) {
      let num = '';
      while (i < src.length && /[0-9.]/.test(src[i])) num += src[i++];
      tokens.push({ type: 'NUMBER', value: parseFloat(num) });
      continue;
    }

    // String literal  (single or double quoted, no escape sequences needed for rule values)
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = src[i++];
          str += ({ n: '\n', t: '\t', r: '\r' }[esc] ?? esc);
        } else {
          str += src[i++];
        }
      }
      if (i >= src.length) throw new SyntaxError('Unterminated string literal in rule');
      i++; // closing quote
      tokens.push({ type: 'STRING', value: str });
      continue;
    }

    // Identifier / keyword
    if (/[a-zA-Z_$]/.test(src[i])) {
      let id = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) id += src[i++];
      if (id === 'true')  { tokens.push({ type: 'BOOLEAN', value: true  }); continue; }
      if (id === 'false') { tokens.push({ type: 'BOOLEAN', value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: 'NULL',    value: null  }); continue; }
      tokens.push({ type: 'IDENT', value: id });
      continue;
    }

    throw new SyntaxError(`Unexpected character '${src[i]}' in rule expression`);
  }

  return tokens;
}

/**
 * Parse a token stream into an AST, then return an evaluator function.
 *
 * Returns: (ctx: object) => boolean|number|string
 */
function parseExpr(tokens) {
  let pos = 0;

  const peek   = ()  => tokens[pos];
  const consume = () => tokens[pos++];
  const expect  = (type, value) => {
    const t = consume();
    if (!t || (type && t.type !== type) || (value !== undefined && t.value !== value)) {
      throw new SyntaxError(
        `Expected ${value ?? type} but got '${t ? t.value : 'end of expression'}'`
      );
    }
    return t;
  };

  // expr → or
  function expr() { return or(); }

  // or → and ( '||' and )*
  function or() {
    let left = and();
    while (peek()?.type === 'OP' && peek()?.value === '||') {
      consume();
      const right = and();
      const l = left, r = right;
      left = (ctx) => l(ctx) || r(ctx);
    }
    return left;
  }

  // and → not ( '&&' not )*
  function and() {
    let left = not();
    while (peek()?.type === 'OP' && peek()?.value === '&&') {
      consume();
      const right = not();
      const l = left, r = right;
      left = (ctx) => l(ctx) && r(ctx);
    }
    return left;
  }

  // not → '!' not | comparison
  function not() {
    if (peek()?.type === 'OP' && peek()?.value === '!') {
      consume();
      const operand = not();
      return (ctx) => !operand(ctx);
    }
    return comparison();
  }

  // comparison → call ( compOp call )*
  const COMP_OPS = new Set(['===', '!==', '>=', '<=', '>', '<']);
  function comparison() {
    let left = call();
    while (peek()?.type === 'OP' && COMP_OPS.has(peek()?.value)) {
      const op = consume().value;
      const right = call();
      const l = left, r = right;
      switch (op) {
        case '===': left = (ctx) => l(ctx) === r(ctx); break;
        case '!==': left = (ctx) => l(ctx) !== r(ctx); break;
        case '>=':  left = (ctx) => l(ctx) >= r(ctx);  break;
        case '<=':  left = (ctx) => l(ctx) <= r(ctx);  break;
        case '>':   left = (ctx) => l(ctx) >  r(ctx);  break;
        case '<':   left = (ctx) => l(ctx) <  r(ctx);  break;
      }
    }
    return left;
  }

  // call → primary ( '.' IDENT '(' argList ')' )*
  // Allows: ctx.tags.includes('premium')
  // Only a safe allowlist of array/string methods may be called.
  const ALLOWED_METHODS = new Set([
    'includes', 'startsWith', 'endsWith',
    'indexOf',  'lastIndexOf',
    'hasOwnProperty',
  ]);

  function call() {
    let base = primary();
    while (peek()?.type === 'DOT') {
      consume(); // consume '.'
      const methodToken = expect('IDENT');
      const methodName  = methodToken.value;

      if (peek()?.type !== 'LPAREN') {
        // Property access without a call — treat as field navigation.
        // Re-insert a virtual field-access step rather than a method call.
        const b = base;
        base = (ctx) => {
          const obj = b(ctx);
          return obj != null ? obj[methodName] : undefined;
        };
        continue;
      }

      // It's a method call — enforce allowlist.
      if (!ALLOWED_METHODS.has(methodName)) {
        throw new SyntaxError(
          `Method '${methodName}' is not permitted in rule expressions. ` +
          `Allowed methods: ${[...ALLOWED_METHODS].join(', ')}`
        );
      }

      expect('LPAREN');
      const args = argList();
      expect('RPAREN');

      const b = base;
      const m = methodName;
      const a = args;
      base = (ctx) => {
        const obj = b(ctx);
        if (obj == null || typeof obj[m] !== 'function') return false;
        return obj[m](...a.map((fn) => fn(ctx)));
      };
    }
    return base;
  }

  // argList → ( expr ( ',' expr )* )?
  function argList() {
    const args = [];
    if (peek()?.type === 'RPAREN') return args; // empty argument list
    args.push(expr());
    while (peek()?.type === 'COMMA') {
      consume();
      args.push(expr());
    }
    return args;
  }

  // primary → literal | '(' expr ')' | IDENT ('.' IDENT)*
  function primary() {
    const t = peek();
    if (!t) throw new SyntaxError('Unexpected end of rule expression');

    // Literals
    if (t.type === 'NUMBER')  { consume(); return () => t.value; }
    if (t.type === 'STRING')  { consume(); return () => t.value; }
    if (t.type === 'BOOLEAN') { consume(); return () => t.value; }
    if (t.type === 'NULL')    { consume(); return () => null;     }

    // Grouped expression
    if (t.type === 'LPAREN') {
      consume();
      const inner = expr();
      expect('RPAREN');
      return inner;
    }

    // Identifier or dotted path  (e.g. ctx, ctx.amount, ctx.address.city)
    if (t.type === 'IDENT') {
      consume();
      const parts = [t.value];
      while (peek()?.type === 'DOT') {
        // Look ahead: if next-next is LPAREN this is a method call — stop here
        // and let call() handle the dispatch.
        const savedPos = pos;
        consume(); // consume '.'
        if (peek()?.type === 'IDENT') {
          // Check the token after the identifier
          const identTok = tokens[pos];
          if (identTok && tokens[pos + 1]?.type === 'LPAREN') {
            // This is `base.method(...)` — back up so call() can process it
            pos = savedPos;
            break;
          }
          parts.push(consume().value);
        } else {
          pos = savedPos;
          break;
        }
      }

      return (ctx) => {
        // The first identifier must be 'ctx'; reject anything else to
        // prevent accessing global objects like process, require, etc.
        if (parts[0] !== 'ctx') {
          throw new SyntaxError(
            `Identifier '${parts[0]}' is not allowed. Rule expressions may only reference 'ctx'.`
          );
        }
        let val = ctx;
        for (let k = 1; k < parts.length; k++) {
          if (val == null) return undefined;
          val = val[parts[k]];
        }
        return val;
      };
    }

    throw new SyntaxError(`Unexpected token '${t.value}' in rule expression`);
  }

  const evaluator = expr();

  if (pos < tokens.length) {
    throw new SyntaxError(
      `Unexpected token '${tokens[pos].value}' after end of rule expression`
    );
  }

  return evaluator;
}

/**
 * evalRule — public entry point.
 *
 * Parses `rule` once (fast for repeated calls) and evaluates it against
 * `context`.  Returns a boolean; throws SyntaxError for bad expressions.
 *
 * @param {string} rule     - e.g. 'ctx.amount > 100'
 * @param {object} context  - the data object exposed as `ctx` in the rule
 * @returns {boolean}
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string' || rule.trim() === '') {
    throw new TypeError('"rule" must be a non-empty string');
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    throw new TypeError('"context" must be a plain object');
  }

  const tokens   = tokenize(rule);
  const evaluate = parseExpr(tokens);
  return Boolean(evaluate(context));
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '"rule" is required and must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: '"context" is required and must be a plain object' });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    const isSyntax = err instanceof SyntaxError || err instanceof TypeError;
    return res.status(400).json({ error: err.message, type: isSyntax ? err.constructor.name : 'EvalError' });
  }

  return res.status(200).json({ result });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = { app, evalRule, tokenize, parseExpr }; // export for testing

