const { evalRule, tokenize, parseExpr } = require('./app.js');

let passed = 0, failed = 0;

function assert(label, got, expected) {
  if (got === expected) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}  →  got ${JSON.stringify(got)}, expected ${JSON.stringify(expected)}`);
    failed++;
  }
}

function assertThrows(label, fn, msgIncludes) {
  try {
    fn();
    console.error(`  ✗  ${label}  →  expected throw but got no error`);
    failed++;
  } catch(e) {
    if (!msgIncludes || e.message.includes(msgIncludes)) {
      console.log(`  ✓  ${label}  (threw: ${e.message})`);
      passed++;
    } else {
      console.error(`  ✗  ${label}  →  threw but msg doesn't include '${msgIncludes}': ${e.message}`);
      failed++;
    }
  }
}

console.log('\n── Comparison operators ──');
assert('> true',             evalRule('ctx.amount > 100',    { amount: 200   }), true);
assert('> false',            evalRule('ctx.amount > 100',    { amount: 50    }), false);
assert('>= boundary true',   evalRule('ctx.amount >= 100',   { amount: 100   }), true);
assert('<= boundary true',   evalRule('ctx.amount <= 100',   { amount: 100   }), true);
assert('< true',             evalRule('ctx.age < 18',        { age: 16       }), true);
assert('=== string true',    evalRule("ctx.role === 'admin'",{ role: 'admin' }), true);
assert('=== string false',   evalRule("ctx.role === 'admin'",{ role: 'user'  }), false);
assert('!== true',           evalRule("ctx.role !== 'admin'",{ role: 'user'  }), true);

console.log('\n── Boolean combinators ──');
assert('&& both true',  evalRule('ctx.age >= 18 && ctx.score > 50', { age: 20, score: 80 }), true);
assert('&& left false', evalRule('ctx.age >= 18 && ctx.score > 50', { age: 15, score: 80 }), false);
assert('|| left true',  evalRule('ctx.vip === true || ctx.score > 50', { vip: true, score: 10 }), true);
assert('|| both false', evalRule('ctx.vip === true || ctx.score > 50', { vip: false, score: 10 }), false);

console.log('\n── Negation ──');
assert('! false field', evalRule('!ctx.banned',       { banned: false }), true);
assert('! true field',  evalRule('!ctx.banned',       { banned: true  }), false);

console.log('\n── Nested context fields ──');
assert('nested path',   evalRule("ctx.address.city === 'NYC'", { address: { city: 'NYC' } }), true);

console.log('\n── Method calls ──');
assert('includes true',    evalRule("ctx.tags.includes('premium')", { tags: ['premium','gold'] }), true);
assert('includes false',   evalRule("ctx.tags.includes('premium')", { tags: ['basic']          }), false);
assert('startsWith true',  evalRule("ctx.email.startsWith('admin')", { email: 'admin@acme.com' }), true);
assert('endsWith true',    evalRule("ctx.email.endsWith('.com')",     { email: 'user@acme.com' }), true);

console.log('\n── Literals ──');
assert('number literal',  evalRule('ctx.score > 0',      { score: 1    }), true);
assert('string literal',  evalRule("ctx.x === 'hello'",  { x: 'hello' }), true);
assert('boolean literal', evalRule('ctx.ok === true',    { ok: true   }), true);
assert('null literal',    evalRule('ctx.x === null',     { x: null    }), true);
assert('grouped parens',  evalRule('(ctx.a > 1) && (ctx.b < 10)', { a: 2, b: 5 }), true);

console.log('\n── Security: forbidden identifiers ──');
assertThrows('process blocked',  () => evalRule('process.env',         {}), "Identifier 'process'");
assertThrows('require blocked',  () => evalRule("require('fs')",        {}), "Unexpected token");
assertThrows('global blocked',   () => evalRule('global.something',    {}), "Identifier 'global'");

console.log('\n── Security: forbidden methods ──');
assertThrows('constructor blocked', () => evalRule('ctx.x.constructor()',  { x: '' }), "not permitted");
assertThrows('toString blocked',    () => evalRule('ctx.x.toString()',     { x: 1  }), "not permitted");
assertThrows('__proto__ call',      () => evalRule('ctx.x.__proto__()',    { x: {} }), "not permitted");

console.log('\n── Input validation ──');
assertThrows('empty rule',    () => evalRule('', {}),   'non-empty string');
assertThrows('null context',  () => evalRule('ctx.x > 1', null), 'plain object');
assertThrows('array context', () => evalRule('ctx.x > 1', []),   'plain object');

console.log(`\n${'─'.repeat(40)}`);
console.log(`  ${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
