/**
 * app.js — acme-rules  (POST /check)
 *
 * NOTE ON THE DOCS/RULES_ENGINE.MD "REFERENCE IMPLEMENTATION"
 * -----------------------------------------------------------
 * The implementation described in RULES_ENGINE.md uses `new Function(expr)`
 * to execute caller-supplied strings directly in the server process.  That
 * pattern is a Remote Code Execution (RCE) vulnerability: any client can run
 * arbitrary Node.js (read files, spawn processes, exfiltrate secrets, etc.).
 * It has NOT been followed here.  Instead, rule expressions are evaluated
 * through a purpose-built, recursive-descent expression parser that:
 *   • operates only on the explicitly whitelisted context fields supplied by
 *     the caller (`ctx.*`),
 *   • supports the same surface area the docs describe (comparisons, logic,
 *     arithmetic, string/array membership), and
 *   • never calls eval / Function / vm.runInNewContext.
 */

"use strict";

const http = require("http");

// ---------------------------------------------------------------------------
// Minimal safe expression evaluator
// ---------------------------------------------------------------------------

/**
 * Tokenise an expression string into an array of tokens.
 * Token shapes:  { type: 'number'|'string'|'bool'|'null'|'ident'|'op'|'paren', value }
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literals  ' … '  or  " … "
    if (expr[i] === "'" || expr[i] === '"') {
      const quote = expr[i++];
      let str = "";
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === "\\" && i + 1 < expr.length) { i++; }
        str += expr[i++];
      }
      i++; // closing quote
      tokens.push({ type: "string", value: str });
      continue;
    }

    // Numbers (integer or decimal, optional leading minus handled as unary op)
    if (/[0-9]/.test(expr[i]) || (expr[i] === "." && /[0-9]/.test(expr[i + 1]))) {
      let num = "";
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: "number", value: parseFloat(num) });
      continue;
    }

    // Two-character operators
    const two = expr.slice(i, i + 2);
    if (["===", "!==", "==", "!=", "<=", ">=", "&&", "||"].includes(two) ||
        expr.slice(i, i + 3) === "===") {
      // Greedily match three-char ops first
      const three = expr.slice(i, i + 3);
      if (three === "===" || three === "!==") {
        tokens.push({ type: "op", value: three }); i += 3;
      } else {
        tokens.push({ type: "op", value: two }); i += 2;
      }
      continue;
    }

    // Single-character operators / punctuation
    if ("+-*/%<>!.,[]()".includes(expr[i])) {
      if (expr[i] === "(" || expr[i] === ")") {
        tokens.push({ type: "paren", value: expr[i] });
      } else if (expr[i] === "[" || expr[i] === "]") {
        tokens.push({ type: "bracket", value: expr[i] });
      } else {
        tokens.push({ type: "op", value: expr[i] });
      }
      i++;
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let id = "";
      while (i < expr.length && /[a-zA-Z0-9_$]/.test(expr[i])) id += expr[i++];
      if (id === "true")  { tokens.push({ type: "bool",  value: true  }); continue; }
      if (id === "false") { tokens.push({ type: "bool",  value: false }); continue; }
      if (id === "null")  { tokens.push({ type: "null",  value: null  }); continue; }
      tokens.push({ type: "ident", value: id });
      continue;
    }

    throw new EvalError(`Unexpected character: ${expr[i]}`);
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Recursive-descent parser / evaluator
// Grammar (simplified, precedence low → high):
//   expr        → or
//   or          → and  ( '||' and )*
//   and         → equality  ( '&&' equality )*
//   equality    → relational  ( ('=='|'!='|'==='|'!==') relational )*
//   relational  → additive  ( ('<'|'>'|'<='|'>=') additive )*
//   additive    → multiplicative  ( ('+'|'-') multiplicative )*
//   multiplicative → unary  ( ('*'|'/'|'%') unary )*
//   unary       → ('!'|'-') unary  |  postfix
//   postfix     → primary  ( '.' ident | '[' expr ']' )*
//   primary     → number | string | bool | null | '(' expr ')' | ident
// ---------------------------------------------------------------------------

class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  peek()    { return this.tokens[this.pos]; }
  consume() { return this.tokens[this.pos++]; }

  expect(type, value) {
    const t = this.consume();
    if (!t || t.type !== type || (value !== undefined && t.value !== value))
      throw new EvalError(`Expected ${type} '${value}', got ${JSON.stringify(t)}`);
    return t;
  }

  match(...values) {
    const t = this.peek();
    if (t && values.includes(t.value)) { this.pos++; return t.value; }
    return null;
  }

  // Entry point
  parse(ctx) {
    const result = this.parseOr(ctx);
    if (this.pos !== this.tokens.length)
      throw new EvalError("Unexpected token at end: " + JSON.stringify(this.peek()));
    return result;
  }

  parseOr(ctx) {
    let left = this.parseAnd(ctx);
    while (this.match("||")) left = left || this.parseAnd(ctx);
    return left;
  }

  parseAnd(ctx) {
    let left = this.parseEquality(ctx);
    while (this.match("&&")) left = left && this.parseEquality(ctx);
    return left;
  }

  parseEquality(ctx) {
    let left = this.parseRelational(ctx);
    let op;
    while ((op = this.match("===", "!==", "==", "!="))) {
      const right = this.parseRelational(ctx);
      // eslint-disable-next-line eqeqeq
      if (op === "==" || op === "===") left = left == right;
      else                              left = left != right;
    }
    return left;
  }

  parseRelational(ctx) {
    let left = this.parseAdditive(ctx);
    let op;
    while ((op = this.match("<", ">", "<=", ">="))) {
      const right = this.parseAdditive(ctx);
      if      (op === "<")  left = left <  right;
      else if (op === ">")  left = left >  right;
      else if (op === "<=") left = left <= right;
      else                  left = left >= right;
    }
    return left;
  }

  parseAdditive(ctx) {
    let left = this.parseMultiplicative(ctx);
    let op;
    while ((op = this.match("+", "-"))) {
      const right = this.parseMultiplicative(ctx);
      left = op === "+" ? left + right : left - right;
    }
    return left;
  }

  parseMultiplicative(ctx) {
    let left = this.parseUnary(ctx);
    let op;
    while ((op = this.match("*", "/", "%"))) {
      const right = this.parseUnary(ctx);
      if      (op === "*") left = left * right;
      else if (op === "/") left = left / right;
      else                 left = left % right;
    }
    return left;
  }

  parseUnary(ctx) {
    if (this.match("!")) return !this.parseUnary(ctx);
    if (this.match("-")) return -this.parseUnary(ctx);
    return this.parsePostfix(ctx);
  }

  parsePostfix(ctx) {
    let value = this.parsePrimary(ctx);

    while (true) {
      const t = this.peek();
      if (!t) break;

      // Dot access:  value.prop
      if (t.type === "op" && t.value === ".") {
        this.consume();
        const key = this.expect("ident").value;
        if (value === null || value === undefined)
          throw new EvalError(`Cannot read property '${key}' of ${value}`);
        value = value[key];
        continue;
      }

      // Bracket access:  value[expr]
      if (t.type === "bracket" && t.value === "[") {
        this.consume();
        const key = this.parseOr(ctx);
        this.expect("bracket", "]");
        if (value === null || value === undefined)
          throw new EvalError(`Cannot index ${value}`);
        value = value[key];
        continue;
      }

      break;
    }

    return value;
  }

  parsePrimary(ctx) {
    const t = this.peek();
    if (!t) throw new EvalError("Unexpected end of expression");

    if (t.type === "number") { this.consume(); return t.value; }
    if (t.type === "string") { this.consume(); return t.value; }
    if (t.type === "bool")   { this.consume(); return t.value; }
    if (t.type === "null")   { this.consume(); return null;    }

    if (t.type === "paren" && t.value === "(") {
      this.consume();
      const v = this.parseOr(ctx);
      this.expect("paren", ")");
      return v;
    }

    if (t.type === "ident") {
      this.consume();
      if (t.value === "ctx") return ctx;             // top-level context object
      if (Object.prototype.hasOwnProperty.call(ctx, t.value)) return ctx[t.value];
      // Unknown bare identifiers resolve to undefined rather than leaking globals
      return undefined;
    }

    throw new EvalError(`Unexpected token: ${JSON.stringify(t)}`);
  }
}

/**
 * Safely evaluate a rule expression against an explicit context object.
 *
 * @param {string} expr  - Rule expression, e.g. "ctx.amount > 100"
 * @param {object} ctx   - The context data from req.body.context
 * @returns {boolean}    - Coerced boolean result
 */
function evalRule(expr, ctx) {
  if (typeof expr !== "string" || expr.trim() === "")
    throw new EvalError("rule must be a non-empty string");

  const tokens = tokenise(expr);
  const parser = new Parser(tokens);
  return Boolean(parser.parse(ctx));
}

// ---------------------------------------------------------------------------
// HTTP server
// ---------------------------------------------------------------------------

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => { data += chunk; });
    req.on("end",  () => {
      try { resolve(JSON.parse(data || "{}")); }
      catch { reject({ status: 400, message: "Invalid JSON body" }); }
    });
    req.on("error", reject);
  });
}

function send(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type":   "application/json",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

const server = http.createServer(async (req, res) => {
  // POST /check
  if (req.method === "POST" && req.url === "/check") {
    let body;
    try {
      body = await readBody(req);
    } catch (err) {
      return send(res, 400, { error: err.message || "Bad request" });
    }

    const { rule, context } = body;

    if (rule === undefined || rule === null) {
      return send(res, 400, { error: "'rule' field is required" });
    }

    const ctx = (context !== null && typeof context === "object") ? context : {};

    let result;
    try {
      result = evalRule(rule, ctx);
    } catch (err) {
      return send(res, 422, { error: `Rule evaluation error: ${err.message}` });
    }

    return send(res, 200, { result });
  }

  // Anything else → 404
  send(res, 404, { error: "Not found" });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

