'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Tokeniser — converts an expression string into a flat token array.
 *
 * Supported tokens
 *   Literals  : numbers (42, 3.14), booleans (true/false), null,
 *               single- or double-quoted strings
 *   Identifiers / member access : ctx.amount, ctx.user.role
 *   Operators : &&  ||  !  ==  !=  ===  !==  <=  >=  <  >
 *   Grouping  : ( )
 *
 * Anything outside this set throws a descriptive error so that an
 * unsupported expression is clearly rejected rather than silently
 * mis-evaluated.
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // Two-char operators (must be checked before single-char)
    const two = expr.slice(i, i + 3);
    if (two === '===' || two === '!==') {
      tokens.push({ type: 'op', value: two }); i += 3; continue;
    }
    const pair = expr.slice(i, i + 2);
    if (['&&', '||', '==', '!=', '<=', '>='].includes(pair)) {
      tokens.push({ type: 'op', value: pair }); i += 2; continue;
    }

    // Single-char operators / grouping
    if (['!', '<', '>', '(', ')'].includes(expr[i])) {
      tokens.push({ type: 'op', value: expr[i] }); i++; continue;
    }

    // Numeric literal
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1]))) {
      let num = '';
      if (expr[i] === '-') { num = '-'; i++; }
