      if (id === 'true')  { tokens.push({ type: 'literal',    value: true  }); continue; }
      if (id === 'false') { tokens.push({ type: 'literal',    value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: 'literal',    value: null  }); continue; }

      // Only allow identifiers that start with "ctx." or are bare "ctx"
      if (id !== 'ctx' && !id.startsWith('ctx.')) {
        throw new Error(
          `Disallowed identifier "${id}" in rule. ` +
          `Only "ctx" and "ctx.<field>" references are permitted.`
        );
      }
      tokens.push({ type: 'identifier', value: id }); continue;
    }

    throw new Error(`Unexpected character "${expr[i]}" in rule expression`);
  }

  return tokens;
}

/**
 * Recursive-descent parser + evaluator.
 *
 * Grammar (precedence, lowest → highest):
 *   expr        → or
 *   or          → and  ( '||' and  )*
 *   and         → equality ( '&&' equality )*
 *   equality    → relational ( ('==' | '!=' | '===' | '!==') relational )*
 *   relational  → unary ( ('<' | '>' | '<=' | '>=') unary )*
 *   unary       → '!' unary | primary
 *   primary     → literal | identifier | '(' expr ')'
 */
function parse(tokens) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function match(...ops) {
    const t = peek();
    if (t && t.type === 'op' && ops.includes(t.value)) {
      consume(); return t.value;
    }
    return null;
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error('Unexpected end of rule expression');

    if (t.type === 'literal') {
      consume(); return () => t.value;
    }

    if (t.type === 'identifier') {
      consume();
      // t.value is e.g. "ctx.user.role" or "ctx"
      return (ctx) => {
        const parts = t.value.split('.');
        // parts[0] is always "ctx" — start from ctx itself
        let val = ctx;
        for (let k = 1; k < parts.length; k++) {
          if (val == null) return undefined;
          val = val[parts[k]];
        }
        return val;
      };
    }

    if (t.type === 'op' && t.value === '(') {
      consume();
