    return parsePrimary();
  }

  function parseRelational() {
    let left = parseUnary();
    let op;
    while ((op = match('<', '>', '<=', '>='))) {
      const right = parseUnary();
      const captured = op;
      const prevLeft = left;
      left = (ctx) => {
        const l = prevLeft(ctx), r = right(ctx);
        if (captured === '<')  return l <  r;
        if (captured === '>')  return l >  r;
        if (captured === '<=') return l <= r;
        if (captured === '>=') return l >= r;
      };
    }
    return left;
  }

  function parseEquality() {
    let left = parseRelational();
    let op;
