      const right = parseRelational();
      const captured = op;
      const prevLeft = left;
      left = (ctx) => {
        const l = prevLeft(ctx), r = right(ctx);
        /* eslint-disable eqeqeq */
        if (captured === '=='  || captured === '===') return l === r;
        if (captured === '!='  || captured === '!==') return l !== r;
        /* eslint-enable eqeqeq */
      };
    }
    return left;
  }

  function parseAnd() {
    let left = parseEquality();
    while (match('&&')) {
      const right = parseEquality();
      const prevLeft = left;
      left = (ctx) => prevLeft(ctx) && right(ctx);
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (match('||')) {
      const right = parseAnd();
      const prevLeft = left;
      left = (ctx) => prevLeft(ctx) || right(ctx);
    }
    return left;
  }

  function parseExpr() { return parseOr(); }

  const evaluatorFn = parseExpr();

  if (pos < tokens.length) {
    throw new Error(
      `Unexpected token "${tokens[pos].value}" — rule expression was not fully consumed`
    );
  }

  return evaluatorFn;
