console.log('\n── Comparison operators ──');
assert('ctx.amount > 100  (true)',  evalRule('ctx.amount > 100',  { amount: 200 }) === true);
assert('ctx.amount > 100  (false)', evalRule('ctx.amount > 100',  { amount: 50  }) === false);
assert('ctx.amount >= 100 (equal)', evalRule('ctx.amount >= 100', { amount: 100 }) === true);
assert('ctx.amount < 5',            evalRule('ctx.amount < 5',    { amount: 3   }) === true);
assert('ctx.amount <= 3',           evalRule('ctx.amount <= 3',   { amount: 3   }) === true);

