const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
// Accepts a restricted expression language and evaluates it against a plain
// `ctx` object supplied by the caller.  Only the following are permitted:
//
//   • Numeric and string literals          42  3.14  "hello"  'world'
//   • Boolean / null literals              true  false  null
//   • Parenthesised sub-expressions        (a + b) * c
//   • Property access on `ctx`            ctx.amount   ctx.user.role
//   • Arithmetic operators                 + - * / %
//   • Comparison operators                 == != < <= > >=
//   • Logical operators                    && || !
//
// Anything outside this set — calls, `require`, `process`, bracket notation
// with dynamic keys, assignment, etc. — is rejected with an error before any
// evaluation takes place.
//
// Implementation: hand-written recursive-descent parser that produces an AST,
// followed by a pure-JS tree-walker.  No `eval`, no `Function`, no `vm`.
// ---------------------------------------------------------------------------

class ParseError extends Error {}
class EvalError  extends Error {}

// ── Tokeniser ──────────────────────────────────────────────────────────────

const TT = {                  // token type constants
  NUM: 'NUM', STR: 'STR', BOOL: 'BOOL', NULL: 'NULL',
  IDENT: 'IDENT', DOT: 'DOT',
  LPAREN: 'LPAREN', RPAREN: 'RPAREN',
  PLUS: 'PLUS', MINUS: 'MINUS', STAR: 'STAR', SLASH: 'SLASH', PCT: 'PCT',
  EQ: 'EQ', NEQ: 'NEQ', LT: 'LT', LTE: 'LTE', GT: 'GT', GTE: 'GTE',
  AND: 'AND', OR: 'OR', BANG: 'BANG',
  EOF: 'EOF',
};

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // numbers
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let raw = '';
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      const v = Number(raw);
      if (isNaN(v)) throw new ParseError(`Invalid numeric literal: ${raw}`);
      tokens.push({ type: TT.NUM, value: v });
      continue;
    }

    // string literals  " … "  or  ' … '
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = src[i++];
          const map = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          if (!(esc in map)) throw new ParseError(`Unknown escape: \\${esc}`);
          str += map[esc];
        } else {
          str += src[i++];
        }
      }
      if (i >= src.length) throw new ParseError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STR, value: str });
      continue;
    }

    // identifiers & keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) name += src[i++];
      if (name === 'true')  { tokens.push({ type: TT.BOOL, value: true });  continue; }
      if (name === 'false') { tokens.push({ type: TT.BOOL, value: false }); continue; }
      if (name === 'null')  { tokens.push({ type: TT.NULL, value: null });  continue; }
      // Block dangerous globals explicitly (belt-and-suspenders; the evaluator
      // also refuses any identifier that is not 'ctx').
      const blocked = ['require', 'process', 'global', 'globalThis',
                       'eval', 'Function', 'module', 'exports', '__dirname',
                       'setTimeout', 'setInterval', 'Buffer', 'fetch'];
      if (blocked.includes(name)) {
        throw new ParseError(`Identifier '${name}' is not allowed in rule expressions`);
      }
      tokens.push({ type: TT.IDENT, value: name });
      continue;
    }

    // two-character operators (must come before single-char checks)
    const two = src.slice(i, i + 2);
    if (two === '==') { tokens.push({ type: TT.EQ  }); i += 2; continue; }
    if (two === '!=') { tokens.push({ type: TT.NEQ }); i += 2; continue; }
    if (two === '<=') { tokens.push({ type: TT.LTE }); i += 2; continue; }
    if (two === '>=') { tokens.push({ type: TT.GTE }); i += 2; continue; }
    if (two === '&&') { tokens.push({ type: TT.AND }); i += 2; continue; }
    if (two === '||') { tokens.push({ type: TT.OR  }); i += 2; continue; }

