    const single = src[i];
    const singleMap = {
      '(': TT.LPAREN, ')': TT.RPAREN,
      '+': TT.PLUS,   '-': TT.MINUS,
      '*': TT.STAR,   '/': TT.SLASH,  '%': TT.PCT,
      '<': TT.LT,     '>': TT.GT,
      '!': TT.BANG,   '.': TT.DOT,
