//
// Grammar (highest precedence last in this list, first in the call chain):
//
//   expr        → or
//   or          → and  ( '||' and )*
//   and         → equality  ( '&&' equality )*
//   equality    → comparison  ( ('==' | '!=') comparison )*
//   comparison  → addition  ( ('<' | '<=' | '>' | '>=') addition )*
//   addition    → multiply  ( ('+' | '-') multiply )*
//   multiply    → unary  ( ('*' | '/' | '%') unary )*
