    }

    case 'binary': {
      const l = evaluate(node.left,  ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '+':  return l + r;
        case '-':  return l - r;
        case '*':  return l * r;
        case '/':  return l / r;
        case '%':  return l % r;
        case '==': return l == r;   // eslint-disable-line eqeqeq
        case '!=': return l != r;   // eslint-disable-line eqeqeq
        case '<':  return l <  r;
        case '<=': return l <= r;
        case '>':  return l >  r;
        case '>=': return l >= r;
        case '&&': return l && r;
        case '||': return l || r;
        default: throw new EvalError(`Unknown binary operator: ${node.op}`);
