  constructor(tokens, ctx) {
    this.tokens = tokens;
    this.pos    = 0;
    this.ctx    = ctx;
  }

  peek()    { return this.tokens[this.pos]; }
  consume() { return this.tokens[this.pos++]; }

  expect(type) {
    const t = this.consume();
    if (t.type !== type) throw new Error(`Expected ${type}, got ${t.type}`);
    return t;
  }

  /** Entry point. */
  parseExpr() {
    const val = this.parseOr();
    if (this.peek().type !== TT.EOF) {
      throw new Error(`Unexpected token '${this.peek().value}' after expression`);
    }
    return val;
  }

  parseOr() {
    let left = this.parseAnd();
    while (this.peek().type === TT.OP && this.peek().value === '||') {
      this.consume();
      const right = this.parseAnd();
      left = left || right;       // preserve JS short-circuit semantics
    }
    return left;
  }

  parseAnd() {
    let left = this.parseCmp();
    while (this.peek().type === TT.OP && this.peek().value === '&&') {
      this.consume();
      const right = this.parseCmp();
      left = left && right;
    }
    return left;
  }

  parseCmp() {
    let left = this.parseUnary();
    const CMP_OPS = ['==', '!=', '>', '>=', '<', '<='];
    while (this.peek().type === TT.OP && CMP_OPS.includes(this.peek().value)) {
      const op = this.consume().value;
      const right = this.parseUnary();
      switch (op) {
        case '==': left = left == right;  break; // eslint-disable-line eqeqeq
        case '!=': left = left != right;  break; // eslint-disable-line eqeqeq
        case '>':  left = left >  right;  break;
        case '>=': left = left >= right;  break;
        case '<':  left = left <  right;  break;
        case '<=': left = left <= right;  break;
      }
    }
    return left;
  }

  parseUnary() {
    if (this.peek().type === TT.OP && this.peek().value === '!') {
      this.consume();
      return !this.parseUnary();
    }
    return this.parsePrimary();
  }

  parsePrimary() {
    const t = this.peek();

