   * @param {string} ident  e.g. "ctx.user.role"
   * @returns {*}
   */
  resolveIdent(ident) {
    const parts = ident.split('.');

    // Only allow ctx-rooted paths
    if (parts[0] !== 'ctx') {
      throw new Error(
        `Identifier '${ident}' is not allowed. ` +
        `Field lookups must start with 'ctx.' (e.g. ctx.amount).`
