// expressions without executing untrusted code.
//
// Supported syntax:  <field>  <op>  <value>
//   field  – dot-separated path into the context object  (e.g. ctx.amount)
//   op     – one of:  >  >=  <  <=  ===  !==  ==  !=
//   value  – a JSON literal: number, boolean, null, or quoted string
//
// Examples:
//   "ctx.amount > 100"
//   "ctx.role === \"admin\""
//   "ctx.active == true"
// ---------------------------------------------------------------------------

/**
 * Safely retrieve a nested value from `obj` using a dot-separated `path`.
 * The leading "ctx." segment is stripped before walking the object so that
 * callers can write natural expressions like "ctx.user.role".
 *
 * Returns `undefined` for any path that does not exist.
 */
function getField(obj, path) {
  const parts = path.replace(/^ctx\./, '').split('.');
  return parts.reduce(
    (cur, key) => (cur !== null && cur !== undefined ? cur[key] : undefined),
    obj,
  );
}

/**
 * Parse and evaluate a single comparison rule expression against `context`.
 *
 * Returns `{ result: boolean }` on success.
 * Throws a descriptive Error when the expression does not match the allowed
 * grammar so callers can surface a 400 response.
 */
function evalRule(expression, context) {
  // Allowed pattern:
  //   <lhs>  <op>  <rhs>
  // where
  //   lhs   = ctx[.<identifier>]+
  //   op    = ===  !==  ==  !=  >=  <=  >  <
  //   rhs   = JSON literal (number | "string" | 'string' | true | false | null)
  const RULE_RE =
    /^\s*(ctx(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+)\s*(===|!==|==|!=|>=|<=|>|<)\s*(-?[0-9]+(?:\.[0-9]+)?|"[^"]*"|'[^']*'|true|false|null)\s*$/;

  const match = RULE_RE.exec(expression);
  if (!match) {
    throw new Error(
      `Invalid rule expression: "${expression}". ` +
        'Expected format: "ctx.<field> <op> <value>" ' +
        'where op is one of ===, !==, ==, !=, >, >=, <, <= ' +
        'and value is a number, boolean, null, or quoted string.',
    );
  }

  const [, lhs, op, rawRhs] = match;

  // Resolve the left-hand side from the supplied context object.
  const lhsValue = getField(context, lhs);

  // Parse the right-hand side as a plain JSON value (safe — no code).
  let rhsValue;
  if (rawRhs === 'true') rhsValue = true;
  else if (rawRhs === 'false') rhsValue = false;
  else if (rawRhs === 'null') rhsValue = null;
  else if (/^-?[0-9]+(?:\.[0-9]+)?$/.test(rawRhs)) rhsValue = Number(rawRhs);
  else rhsValue = rawRhs.slice(1, -1); // strip surrounding quotes from strings

  // Evaluate using an explicit operator map — no eval, no Function().
  const ops = {
    '===': (a, b) => a === b,
    '!==': (a, b) => a !== b,
    '==':  (a, b) => a == b,  // eslint-disable-line eqeqeq
    '!=':  (a, b) => a != b,  // eslint-disable-line eqeqeq
    '>':   (a, b) => a > b,
    '>=':  (a, b) => a >= b,
    '<':   (a, b) => a < b,
    '<=':  (a, b) => a <= b,
  };

  return ops[op](lhsValue, rhsValue);
}

