/**
 * acme-rules — Dynamic Rule Engine
 *
 * POST /check
 *   Body: { rule: <expression>, context: <object> }
 *   Returns: { result: true|false }
 *
 * SECURITY NOTE
 * -------------
 * docs/RULES_ENGINE.md proposes evaluating rule expressions via new Function(),
 * which executes arbitrary caller-supplied JavaScript with full server privileges.
 * That pattern is a Remote Code Execution (RCE) vulnerability and is NOT used here.
 *
 * Instead, rule expressions are evaluated by a safe, sandboxed evaluator that:
 *   - Parses only a restricted expression grammar (comparisons, logical ops, literals)
 *   - Resolves identifiers exclusively against the caller-supplied context object
 *   - Never accesses Node globals (process, require, fs, etc.)
 *   - Rejects any rule that references disallowed constructs at parse time
 *
 * Supported syntax
 * ----------------
 *  Operands   : numeric literals, string literals, boolean literals (true/false),
 *               null, context field paths (e.g. ctx.amount, ctx.user.role)
 *  Comparison : ==  !=  ===  !==  <  <=  >  >=
 *  Logical    : &&  ||  !
 *  Grouping   : ( )
 *
 * Examples
 * --------
 *  ctx.amount > 100
 *  ctx.user.role === "admin" && ctx.user.active !== false
 *  !(ctx.score < 50) || ctx.override === true
 */

"use strict";

const express = require("express");

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Tokenise a rule expression into a flat array of tokens.
 * Recognised token types: NUMBER, STRING, BOOLEAN, NULL, IDENT, OP, LPAREN, RPAREN.
 *
 * Throws a SyntaxError for any character sequence that does not belong to the
 * restricted grammar, preventing unknown constructs from reaching the evaluator.
 *
 * @param {string} source
 * @returns {{ type: string, value: * }[]}
 */
function tokenise(source) {
  const tokens = [];
  let i = 0;

  while (i < source.length) {
    // Skip whitespace
    if (/\s/.test(source[i])) { i++; continue; }

    // String literals  ' … '  or  " … "
    if (source[i] === '"' || source[i] === "'") {
      const quote = source[i++];
      let str = "";
      while (i < source.length && source[i] !== quote) {
        if (source[i] === "\\" && i + 1 < source.length) {
          const esc = source[++i];
          const escapes = { n: "\n", t: "\t", r: "\r", "\\": "\\", "'": "'", '"': '"' };
          str += esc in escapes ? escapes[esc] : esc;
        } else {
          str += source[i];
        }
        i++;
      }
      if (i >= source.length) throw new SyntaxError("Unterminated string literal");
      i++; // closing quote
      tokens.push({ type: "STRING", value: str });
      continue;
    }

    // Numeric literals (integer or decimal, optional leading minus handled as unary)
    if (/[0-9]/.test(source[i]) || (source[i] === "-" && /[0-9]/.test(source[i + 1] || ""))) {
      let num = "";
      if (source[i] === "-") num += source[i++];
      while (i < source.length && /[0-9.]/.test(source[i])) num += source[i++];
      tokens.push({ type: "NUMBER", value: Number(num) });
      continue;
    }

    // Two-character operators: ===  !==  ==  !=  <=  >=  &&  ||
    if (i + 2 < source.length) {
      const three = source.slice(i, i + 3);
      if (three === "===" || three === "!==") {
        tokens.push({ type: "OP", value: three }); i += 3; continue;
      }
    }
    if (i + 1 < source.length) {
      const two = source.slice(i, i + 2);
      if (["==", "!=", "<=", ">=", "&&", "||"].includes(two)) {
        tokens.push({ type: "OP", value: two }); i += 2; continue;
      }
    }

    // Single-character operators and punctuation
    if ("<>!".includes(source[i])) {
      tokens.push({ type: "OP", value: source[i++] }); continue;
    }
    if (source[i] === "(") { tokens.push({ type: "LPAREN" }); i++; continue; }
    if (source[i] === ")") { tokens.push({ type: "RPAREN" }); i++; continue; }

    // Identifiers and keywords (ctx.*, true, false, null)
    if (/[a-zA-Z_$]/.test(source[i])) {
      let ident = "";
      // Allow dotted paths: ctx.user.role
      while (i < source.length && /[a-zA-Z0-9_$.]/.test(source[i])) ident += source[i++];

      // Reject trailing / double dots
      if (ident.endsWith(".") || ident.includes("..")) {
        throw new SyntaxError(`Invalid identifier: "${ident}"`);
      }

      if (ident === "true")       { tokens.push({ type: "BOOLEAN", value: true });  continue; }
      if (ident === "false")      { tokens.push({ type: "BOOLEAN", value: false }); continue; }
      if (ident === "null")       { tokens.push({ type: "NULL",    value: null });  continue; }

      // Only allow identifiers that start with "ctx." or are exactly "ctx"
      if (ident !== "ctx" && !ident.startsWith("ctx.")) {
        throw new SyntaxError(
          `Identifier "${ident}" is not allowed. Rule identifiers must start with "ctx."`
        );
      }

      tokens.push({ type: "IDENT", value: ident }); continue;
    }

    throw new SyntaxError(`Unexpected character "${source[i]}" at position ${i}`);
  }

  return tokens;
}

/**
 * Recursive-descent parser + evaluator over the token stream.
 * Grammar (precedence, lowest → highest):
 *
 *   expr   → and  ( '||' and )*
 *   and    → not  ( '&&' not )*
 *   not    → '!' not  |  compare
 *   compare→ atom ( ( '==' | '!=' | '===' | '!==' | '<' | '<=' | '>' | '>=' ) atom )?
 *   atom   → NUMBER | STRING | BOOLEAN | NULL | IDENT | '(' expr ')'
 *
 * @param {*[]} tokens
 * @param {object} ctx  Caller-supplied context object
 * @returns {boolean}
 */
function parseAndEval(tokens, ctx) {
  let pos = 0;

  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr() {
    let left = parseAnd();
    while (peek()?.type === "OP" && peek()?.value === "||") {
      consume();
      const right = parseAnd();
      left = left || right;
    }
    return left;
  }

  function parseAnd() {
    let left = parseNot();
    while (peek()?.type === "OP" && peek()?.value === "&&") {
      consume();
      const right = parseNot();
      left = left && right;
    }
    return left;
  }

  function parseNot() {
    if (peek()?.type === "OP" && peek()?.value === "!") {
      consume();
      return !parseNot();
    }
    return parseCompare();
  }

  function parseCompare() {
    const left = parseAtom();
    const opToken = peek();
    const compareOps = ["==", "!=", "===", "!==", "<", "<=", ">", ">="];
    if (opToken?.type === "OP" && compareOps.includes(opToken.value)) {
      consume();
      const right = parseAtom();
      switch (opToken.value) {
        case "==":  return left == right;   // eslint-disable-line eqeqeq
        case "!=":  return left != right;   // eslint-disable-line eqeqeq
        case "===": return left === right;
        case "!==": return left !== right;
        case "<":   return left < right;
        case "<=":  return left <= right;
        case ">":   return left > right;
        case ">=":  return left >= right;
      }
    }
    return left;
  }

  function parseAtom() {
    const token = peek();
    if (!token) throw new SyntaxError("Unexpected end of rule expression");

    if (token.type === "NUMBER" || token.type === "STRING" ||
        token.type === "BOOLEAN" || token.type === "NULL") {
      consume();
      return token.value;
    }

    if (token.type === "IDENT") {
      consume();
      return resolveIdent(token.value, ctx);
    }

    if (token.type === "LPAREN") {
      consume();
      const val = parseExpr();
      if (peek()?.type !== "RPAREN") throw new SyntaxError("Expected closing ')'");
      consume();
      return val;
    }

    throw new SyntaxError(`Unexpected token "${token.type}" ("${token.value}")`);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after end of expression: "${tokens[pos].value}"`);
  }

  return result;
}

/**
 * Safely walk a dotted path (e.g. "ctx.user.role") into the context object.
 * The leading "ctx" segment is replaced by the actual context object.
 * Returns undefined for any missing segment rather than throwing.
 *
 * @param {string} ident  Dotted path starting with "ctx"
 * @param {object} ctx
 * @returns {*}
 */
function resolveIdent(ident, ctx) {
  const parts = ident.split(".");
  // parts[0] is always "ctx" (enforced by tokeniser); skip it.
  let value = ctx;
  for (let i = 1; i < parts.length; i++) {
    if (value === null || value === undefined) return undefined;
    // Disallow prototype chain traversal
    if (!Object.prototype.hasOwnProperty.call(value, parts[i])) return undefined;
    value = value[parts[i]];
  }
  return value;
}

/**
 * Public entry point: evaluate a rule expression against a context object.
 *
 * @param {string} rule    Restricted expression, e.g. 'ctx.amount > 100'
 * @param {object} context Plain object of facts
 * @returns {boolean}
 */
function evalRule(rule, context) {
  if (typeof rule !== "string" || rule.trim() === "") {
    throw new TypeError("rule must be a non-empty string");
  }
  if (context === null || typeof context !== "object" || Array.isArray(context)) {
    throw new TypeError("context must be a plain object");
  }

  const tokens = tokenise(rule);
  const result = parseAndEval(tokens, context);
  return Boolean(result);
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== "string" || rule.trim() === "") {
    return res.status(400).json({ error: "rule must be a non-empty string" });
  }
  if (context === undefined || context === null || typeof context !== "object" || Array.isArray(context)) {
    return res.status(400).json({ error: "context must be a plain object" });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    if (err instanceof SyntaxError || err instanceof TypeError) {
      return res.status(400).json({ error: `Invalid rule: ${err.message}` });
    }
    // Unexpected internal error — don't leak details
    console.error("evalRule unexpected error:", err);
    return res.status(500).json({ error: "Internal server error" });
  }

  return res.status(200).json({ result });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));

module.exports = { app, evalRule }; // export for testing

"use strict";

/**
 * Tests for POST /check and the underlying evalRule function.
 *
 * Run with:  node test.js
 */

const { evalRule } = require("./app");

let passed = 0;
let failed = 0;

function assert(description, actual, expected) {
  if (actual === expected) {
    console.log(`  ✓ ${description}`);
    passed++;
  } else {
    console.error(`  ✗ ${description}`);
    console.error(`      expected: ${expected}`);
    console.error(`      actual  : ${actual}`);
    failed++;
  }
}

function assertThrows(description, fn, messageFragment) {
  try {
    fn();
    console.error(`  ✗ ${description} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (!messageFragment || err.message.includes(messageFragment)) {
      console.log(`  ✓ ${description}`);
      passed++;
    } else {
      console.error(`  ✗ ${description}`);
      console.error(`      expected message containing: "${messageFragment}"`);
      console.error(`      actual message: "${err.message}"`);
      failed++;
    }
  }
}

// ---------------------------------------------------------------------------
console.log("\nComparison operators");
// ---------------------------------------------------------------------------

const numCtx = { amount: 150, score: 42 };
assert("ctx.amount > 100  → true",  evalRule("ctx.amount > 100",  numCtx), true);
assert("ctx.amount > 200  → false", evalRule("ctx.amount > 200",  numCtx), false);
assert("ctx.amount < 200  → true",  evalRule("ctx.amount < 200",  numCtx), true);
assert("ctx.amount >= 150 → true",  evalRule("ctx.amount >= 150", numCtx), true);
assert("ctx.amount <= 150 → true",  evalRule("ctx.amount <= 150", numCtx), true);
assert("ctx.amount == 150 → true",  evalRule("ctx.amount == 150", numCtx), true);
assert("ctx.amount != 100 → true",  evalRule("ctx.amount != 100", numCtx), true);
assert('ctx.amount === 150 → true', evalRule("ctx.amount === 150", numCtx), true);
assert('ctx.amount !== 99  → true', evalRule("ctx.amount !== 99",  numCtx), true);

// ---------------------------------------------------------------------------
console.log("\nString comparisons");
// ---------------------------------------------------------------------------

const strCtx = { user: { role: "admin", active: true } };
assert('ctx.user.role === "admin" → true',  evalRule('ctx.user.role === "admin"', strCtx), true);
assert('ctx.user.role === "guest" → false', evalRule('ctx.user.role === "guest"', strCtx), false);
assert("ctx.user.role === 'admin' (single quotes) → true",
  evalRule("ctx.user.role === 'admin'", strCtx), true);

// ---------------------------------------------------------------------------
console.log("\nBoolean and null literals");
// ---------------------------------------------------------------------------

const boolCtx = { active: true, deleted: false, ref: null };
assert("ctx.active === true  → true",  evalRule("ctx.active === true",  boolCtx), true);
assert("ctx.deleted === false → true", evalRule("ctx.deleted === false", boolCtx), true);
assert("ctx.ref === null → true",      evalRule("ctx.ref === null",      boolCtx), true);

// ---------------------------------------------------------------------------
console.log("\nLogical operators");
// ---------------------------------------------------------------------------

const logCtx = { amount: 200, role: "admin", score: 30 };
assert("&& both true  → true",
  evalRule('ctx.amount > 100 && ctx.role === "admin"', logCtx), true);
assert("&& one false  → false",
  evalRule('ctx.amount > 100 && ctx.role === "guest"', logCtx), false);
assert("|| one true   → true",
  evalRule('ctx.score > 50 || ctx.amount > 100', logCtx), true);
assert("|| both false → false",
  evalRule('ctx.score > 50 || ctx.amount > 300', logCtx), false);

// ---------------------------------------------------------------------------
console.log("\nUnary NOT");
// ---------------------------------------------------------------------------

assert("!(ctx.score < 50) → false when score=30",
  evalRule("!(ctx.score < 50)", { score: 30 }), false);
assert("!(ctx.score < 50) → true  when score=80",
  evalRule("!(ctx.score < 50)", { score: 80 }), true);

// ---------------------------------------------------------------------------
console.log("\nGrouping / parentheses");
// ---------------------------------------------------------------------------

const grpCtx = { a: 1, b: 2, c: 3 };
assert("(ctx.a < ctx.b) && (ctx.b < ctx.c) → true",
  evalRule("(ctx.a < ctx.b) && (ctx.b < ctx.c)", grpCtx), true);

// ---------------------------------------------------------------------------
console.log("\nNested context paths");
// ---------------------------------------------------------------------------

const deepCtx = { user: { profile: { level: 5 } } };
assert("ctx.user.profile.level >= 5 → true",
  evalRule("ctx.user.profile.level >= 5", deepCtx), true);
assert("ctx.user.profile.level >= 10 → false",
  evalRule("ctx.user.profile.level >= 10", deepCtx), false);

// ---------------------------------------------------------------------------
console.log("\nMissing context fields");
// ---------------------------------------------------------------------------

assert("missing field === undefined → true",
  evalRule("ctx.missing === null", { amount: 1 }), false);
assert("missing field returns undefined (coerces to false)",
  evalRule("ctx.missing > 0", {}), false);

// ---------------------------------------------------------------------------
console.log("\nSecurity: disallowed identifiers are rejected");
// ---------------------------------------------------------------------------

assertThrows(
  "process.exit() is rejected",
  () => evalRule("process.exit(1)", {}),
  'must start with "ctx."'
);
assertThrows(
  "require() is rejected",
  () => evalRule("require('fs')", {}),
  'must start with "ctx."'
);
assertThrows(
  "global is rejected",
  () => evalRule("global.process.exit(0)", {}),
  'must start with "ctx."'
);
assertThrows(
  "__proto__ traversal via IDENT is rejected",
  () => evalRule("__proto__.isAdmin === true", {}),
  'must start with "ctx."'
);

// ---------------------------------------------------------------------------
console.log("\nSecurity: prototype chain traversal via dotted path is blocked");
// ---------------------------------------------------------------------------

// hasOwnProperty check means ctx.__proto__.xxx does not resolve via the chain
assert("ctx.__proto__ lookup returns undefined (not prototype)",
  evalRule("ctx.__proto__ === null", { __proto__: null }), false);

// ---------------------------------------------------------------------------
console.log("\nSyntax errors are surfaced cleanly");
// ---------------------------------------------------------------------------

assertThrows("unterminated string",   () => evalRule('ctx.x === "hello', {}), "Unterminated string");
assertThrows("unexpected character",  () => evalRule("ctx.x @ 1", {}),        "Unexpected character");
assertThrows("empty rule",            () => evalRule("", {}),                  "non-empty string");
assertThrows("trailing junk",         () => evalRule("ctx.x > 1 $$$", {}),    "Unexpected character");

// ---------------------------------------------------------------------------
console.log("\nInput validation");
// ---------------------------------------------------------------------------

assertThrows("null context",   () => evalRule("ctx.x > 1", null),  "plain object");
assertThrows("array context",  () => evalRule("ctx.x > 1", []),    "plain object");
assertThrows("number context", () => evalRule("ctx.x > 1", 42),    "plain object");

// ---------------------------------------------------------------------------
console.log(`\n${"─".repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);

