/**
 * lib/rule-engine.js
 *
 * Self-contained, sandboxed rule evaluator.
 * Zero external dependencies — only Node built-ins.
 *
 * SECURITY NOTE — why `new Function` / `eval` is NOT used:
 * ─────────────────────────────────────────────────────────────────────
 * docs/RULES_ENGINE.md suggests:
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * Executing a caller-supplied string as live JavaScript is a Remote
 * Code Execution (RCE) vulnerability (OWASP A03:2021 / CWE-94).
 * Any client that can reach POST /check could run arbitrary Node.js
 * code: read env-vars / secrets, exfiltrate data, delete files, or
 * take over the process entirely.
 *
 * Instead this module:
 *   1. Tokenises the rule string with a hand-written lexer.
 *   2. Parses the token stream into an AST with a recursive-descent
 *      parser (no eval, no Function constructor, no vm module).
 *   3. Walks the AST with an evaluator whose identifier resolution is
 *      limited exclusively to the caller-supplied context object.
 *      `globalThis`, `process`, `require`, and every other host object
 *      are completely unreachable.
 */

'use strict';

// ─── Custom error class ───────────────────────────────────────────────────────

class RuleError extends Error {
  constructor(msg) { super(msg); this.name = 'RuleError'; }
}

// ─── Token types ──────────────────────────────────────────────────────────────

const TT = {
  NUMBER:  'NUMBER',   // 42 | 3.14
  STRING:  'STRING',   // 'hello' | "hello"
  BOOL:    'BOOL',     // true | false
  NULL:    'NULL',     // null
  IDENT:   'IDENT',    // foo | ctx
  DOT:     'DOT',      // .
  LBRACK:  'LBRACK',  // [
  RBRACK:  'RBRACK',  // ]
  LPAREN:  'LPAREN',  // (
  RPAREN:  'RPAREN',  // )
  BANG:    'BANG',    // !
  AND:     'AND',     // &&
  OR:      'OR',      // ||
  EQ:      'EQ',      // ==  ===
  NEQ:     'NEQ',     // !=  !==
  LT:      'LT',      // <
  LTE:     'LTE',     // <=
  GT:      'GT',      // >
  GTE:     'GTE',     // >=
  PLUS:    'PLUS',    // +
  MINUS:   'MINUS',   // -
  STAR:    'STAR',    // *
  SLASH:   'SLASH',   // /
  PERCENT: 'PERCENT', // %
  EOF:     'EOF',
};

// ─── Tokeniser ────────────────────────────────────────────────────────────────

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // numbers
    if (/[0-9]/.test(src[i]) || (src[i] === '.' && /[0-9]/.test(src[i + 1]))) {
      let raw = '';
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      tokens.push({ type: TT.NUMBER, value: Number(raw) });
      continue;
    }

    // string literals
    if (src[i] === "'" || src[i] === '"') {
      const quote = src[i++];
      let s = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') { i++; s += src[i++]; }
        else s += src[i++];
      }
      if (i >= src.length) throw new RuleError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STRING, value: s });
      continue;
    }

    // three-char operators
    const three = src.slice(i, i + 3);
    if (three === '===') { tokens.push({ type: TT.EQ  }); i += 3; continue; }
    if (three === '!==') { tokens.push({ type: TT.NEQ }); i += 3; continue; }

    // two-char operators
    const two = src.slice(i, i + 2);
    if (two === '&&') { tokens.push({ type: TT.AND }); i += 2; continue; }
    if (two === '||') { tokens.push({ type: TT.OR  }); i += 2; continue; }
    if (two === '==') { tokens.push({ type: TT.EQ  }); i += 2; continue; }
    if (two === '!=') { tokens.push({ type: TT.NEQ }); i += 2; continue; }
    if (two === '<=') { tokens.push({ type: TT.LTE }); i += 2; continue; }
    if (two === '>=') { tokens.push({ type: TT.GTE }); i += 2; continue; }

    // single-char operators & punctuation
    switch (src[i]) {
      case '.': tokens.push({ type: TT.DOT     }); i++; break;
      case '[': tokens.push({ type: TT.LBRACK  }); i++; break;
      case ']': tokens.push({ type: TT.RBRACK  }); i++; break;
      case '(': tokens.push({ type: TT.LPAREN  }); i++; break;
      case ')': tokens.push({ type: TT.RPAREN  }); i++; break;
      case '!': tokens.push({ type: TT.BANG    }); i++; break;
      case '<': tokens.push({ type: TT.LT      }); i++; break;
      case '>': tokens.push({ type: TT.GT      }); i++; break;
      case '+': tokens.push({ type: TT.PLUS    }); i++; break;
      case '-': tokens.push({ type: TT.MINUS   }); i++; break;
      case '*': tokens.push({ type: TT.STAR    }); i++; break;
      case '/': tokens.push({ type: TT.SLASH   }); i++; break;
      case '%': tokens.push({ type: TT.PERCENT }); i++; break;
      default:
        if (/[a-zA-Z_$]/.test(src[i])) {
          let name = '';
          while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) name += src[i++];
          if (name === 'true')  { tokens.push({ type: TT.BOOL, value: true  }); break; }
          if (name === 'false') { tokens.push({ type: TT.BOOL, value: false }); break; }
          if (name === 'null')  { tokens.push({ type: TT.NULL, value: null  }); break; }
          tokens.push({ type: TT.IDENT, value: name });
          break;
        }
        throw new RuleError(`Unexpected character: "${src[i]}"`);
    }
  }

  tokens.push({ type: TT.EOF });
  return tokens;
}

// ─── Parser (recursive-descent, standard JS precedence) ───────────────────────
/*
 * Grammar (lowest → highest precedence):
 *
 *   expr    → or
 *   or      → and   ( '||' and   )*
 *   and     → eq    ( '&&' eq    )*
 *   eq      → cmp   ( ('=='|'!='|'==='|'!==') cmp )*
 *   cmp     → add   ( ('<'|'<='|'>'|'>=')     add )*
 *   add     → mul   ( ('+'|'-') mul )*
 *   mul     → unary ( ('*'|'/'|'%') unary )*
 *   unary   → ('!'|'-') unary | postfix
 *   postfix → primary ( '.' IDENT | '[' expr ']' )*
 *   primary → NUMBER | STRING | BOOL | NULL | IDENT | '(' expr ')'
 */

function parse(tokens) {
  let pos = 0;

  const peek  = ()        => tokens[pos];
  const next  = ()        => tokens[pos++];
  const eat   = (type)    => {
    if (peek().type !== type)
      throw new RuleError(`Expected ${type} but got ${peek().type}`);
    return next();
  };
  const match = (...types) => types.includes(peek().type) ? next() : null;

  function expr()   { return or(); }

  function or() {
    let left = and();
    while (peek().type === TT.OR) {
      next();
      left = { kind: 'binary', op: '||', left, right: and() };
    }
    return left;
  }

  function and() {
    let left = eq();
    while (peek().type === TT.AND) {
      next();
      left = { kind: 'binary', op: '&&', left, right: eq() };
    }
    return left;
  }

  function eq() {
    let left = cmp();
    let tok;
    while ((tok = match(TT.EQ, TT.NEQ))) {
      left = { kind: 'binary', op: tok.type === TT.EQ ? '==' : '!=',
               left, right: cmp() };
    }
    return left;
  }

  function cmp() {
    let left = add();
    let tok;
    const opMap = { [TT.LT]: '<', [TT.LTE]: '<=', [TT.GT]: '>', [TT.GTE]: '>=' };
    while ((tok = match(TT.LT, TT.LTE, TT.GT, TT.GTE))) {
      left = { kind: 'binary', op: opMap[tok.type], left, right: add() };
    }
    return left;
  }

  function add() {
    let left = mul();
    let tok;
    while ((tok = match(TT.PLUS, TT.MINUS))) {
      left = { kind: 'binary', op: tok.type === TT.PLUS ? '+' : '-',
               left, right: mul() };
    }
    return left;
  }

  function mul() {
    let left = unary();
    let tok;
    const opMap = { [TT.STAR]: '*', [TT.SLASH]: '/', [TT.PERCENT]: '%' };
    while ((tok = match(TT.STAR, TT.SLASH, TT.PERCENT))) {
      left = { kind: 'binary', op: opMap[tok.type], left, right: unary() };
    }
    return left;
  }

  function unary() {
    if (peek().type === TT.BANG)  { next(); return { kind: 'unary', op: '!', operand: unary() }; }
    if (peek().type === TT.MINUS) { next(); return { kind: 'unary', op: '-', operand: unary() }; }
    return postfix();
  }

  function postfix() {
    let node = primary();
    for (;;) {
      if (peek().type === TT.DOT) {
        next();
        const prop = eat(TT.IDENT).value;
        node = { kind: 'member', object: node, prop, computed: false };
      } else if (peek().type === TT.LBRACK) {
        next();
        const key = expr();
        eat(TT.RBRACK);
        node = { kind: 'member', object: node, prop: key, computed: true };
      } else {
        break;
      }
    }
    return node;
  }

  function primary() {
    const tok = peek();

    if ([TT.NUMBER, TT.STRING, TT.BOOL, TT.NULL].includes(tok.type)) {
      next();
      return { kind: 'literal', value: tok.value };
    }
    if (tok.type === TT.IDENT) {
      next();
      return { kind: 'identifier', name: tok.value };
    }
    if (tok.type === TT.LPAREN) {
      next();
      const inner = expr();
      eat(TT.RPAREN);
      return inner;
    }

    throw new RuleError(`Unexpected token: ${tok.type}`);
  }

  const tree = expr();
  if (peek().type !== TT.EOF) {
    throw new RuleError(`Unexpected token after expression: "${peek().type}"`);
  }
  return tree;
}

// ─── Evaluator (safe AST walker) ──────────────────────────────────────────────

/**
 * Walk the AST and compute a value.
 *
 * `scope` is the ONLY source of identifier values.
 * globalThis / process / require are completely unreachable.
 */
function evaluate(node, scope) {
  switch (node.kind) {

    case 'literal':
      return node.value;

    case 'identifier': {
      // Only look up names in the explicit scope — never in globalThis.
      return Object.prototype.hasOwnProperty.call(scope, node.name)
        ? scope[node.name]
        : undefined;
    }

    case 'member': {
      const obj = evaluate(node.object, scope);
      if (obj === null || obj === undefined) return undefined;

      // Functions are never safe to hand back (could be called later, or used
      // to escape the sandbox via .constructor / .call / .apply).
      if (typeof obj === 'function') {
        throw new RuleError('Member access on a function is not allowed');
      }

      const key = node.computed ? evaluate(node.prop, scope) : node.prop;

      // Block prototype-climbing escape hatches.
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
        throw new RuleError(`Property "${key}" is not accessible`);
      }

      if (typeof obj === 'object') {
        return Object.prototype.hasOwnProperty.call(obj, key) ? obj[key] : undefined;
      }

      return undefined;
    }

    case 'unary': {
      const v = evaluate(node.operand, scope);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      throw new RuleError(`Unknown unary operator: "${node.op}"`);
    }

    case 'binary': {
      // Evaluate left first; short-circuit before evaluating right for && / ||.
      const l = evaluate(node.left, scope);
      if (node.op === '||') return l || evaluate(node.right, scope);
      if (node.op === '&&') return l && evaluate(node.right, scope);

      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '==':  return l == r;    // eslint-disable-line eqeqeq
        case '!=':  return l != r;    // eslint-disable-line eqeqeq
        case '<':   return l <  r;
        case '<=':  return l <= r;
        case '>':   return l >  r;
        case '>=':  return l >= r;
        case '+':   return l +  r;
        case '-':   return l -  r;
        case '*':   return l *  r;
        case '/':   return l /  r;
        case '%':   return l %  r;
        default:    throw new RuleError(`Unknown binary operator: "${node.op}"`);
      }
    }

    default:
      throw new RuleError(`Unknown AST node kind: "${node.kind}"`);
  }
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Safely evaluate a rule expression against a plain-object context.
 *
 * @param  {string} ruleExpr  Rule to evaluate, e.g. `'ctx.amount > 100'`
 * @param  {object} context   Data object the rule runs against
 * @returns {*}               Result of the expression (usually boolean)
 * @throws  {RuleError}       On invalid input, syntax errors, or forbidden access
 */
function evalRule(ruleExpr, context) {
  if (typeof ruleExpr !== 'string' || ruleExpr.trim() === '') {
    throw new RuleError('rule must be a non-empty string');
  }
  // Expose `ctx` as the documented top-level identifier.
  const scope  = { ctx: context };
  const tokens = tokenise(ruleExpr);
  const ast    = parse(tokens);
  return evaluate(ast, scope);
}

module.exports = { evalRule, RuleError };

/**
 * app.js — acme-rules  POST /check endpoint
 *
 * SECURITY NOTE — why the RULES_ENGINE.md reference is NOT followed:
 * ─────────────────────────────────────────────────────────────────────
 * The reference implementation in docs/RULES_ENGINE.md calls
 *
 *   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
 *
 * which executes a **caller-supplied string as live JavaScript** on the
 * server.  This is a Remote Code Execution (RCE) vulnerability
 * (OWASP A03:2021 – Injection / CWE-94).  Any client that can reach the
 * endpoint can run arbitrary Node.js code: read secrets, exfiltrate data,
 * delete files, or take over the process.
 *
 * Instead, rule evaluation is delegated to lib/rule-engine.js, which
 * parses the expression into an AST and walks it in a fully sandboxed
 * evaluator.  No eval, no Function constructor, no vm module — and the
 * host environment is completely unreachable from a rule expression.
 */

'use strict';

const express            = require('express');
const { evalRule, RuleError } = require('./lib/rule-engine');

const app = express();
app.use(express.json());

// ─── POST /check ──────────────────────────────────────────────────────────────

/**
 * POST /check
 *
 * Body (JSON):
 *   {
 *     "rule":    "<expression>",   // required — rule to evaluate
 *     "context": { … }            // required — data the rule runs against
 *   }
 *
 * Responses:
 *   200  { "result": <value>   }   — rule evaluated successfully
 *   400  { "error":  "<msg>"   }   — missing/invalid fields or rule syntax error
 *   500  { "error":  "Internal error" } — unexpected server error
 *
 * Supported expression syntax:
 *   • Property access  : ctx.amount  /  ctx.user.role  /  ctx.items[0]
 *   • Comparisons      : ==  !=  <  <=  >  >=
 *   • Logical          : &&  ||  !
 *   • Arithmetic       : +  -  *  /  %  (unary -)
 *   • Literals         : numbers, strings ('…' / "…"), true, false, null
 *   • Parentheses      : (ctx.a + ctx.b) * 2
 *
 * Examples:
 *   { "rule": "ctx.amount > 100",            "context": { "amount": 150 } }
 *   { "rule": "ctx.role == 'admin'",         "context": { "role": "admin" } }
 *   { "rule": "ctx.score >= 90 && ctx.pass", "context": { "score": 95, "pass": true } }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '`rule` must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be a non-null object' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    if (err instanceof RuleError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('Unexpected error in POST /check:', err);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// ─── Start ────────────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));
}

module.exports = { app, evalRule, RuleError };

