 */

'use strict';

const assert    = require('assert');
const http      = require('http');
const { evalRule, RuleError } = require('../lib/rule-engine');

let passed = 0;
let failed = 0;

function test(description, fn) {
  try {
    fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

function assertRuleError(description, ruleExpr, ctx = {}) {
  test(description, () =>
    assert.throws(() => evalRule(ruleExpr, ctx), RuleError));
}

// ─── Literals ─────────────────────────────────────────────────────────────────
console.log('\nLiterals');
test('integer literal',       () => assert.strictEqual(evalRule('42',      {}), 42));
test('float literal',         () => assert.strictEqual(evalRule('3.14',    {}), 3.14));
test('double-quoted string',  () => assert.strictEqual(evalRule('"hello"', {}), 'hello'));
test('single-quoted string',  () => assert.strictEqual(evalRule("'world'", {}), 'world'));
test('escaped char in string',() => assert.strictEqual(evalRule("'it\\'s'",{}), "it's"));
test('boolean true',          () => assert.strictEqual(evalRule('true',    {}), true));
test('boolean false',         () => assert.strictEqual(evalRule('false',   {}), false));
test('null literal',          () => assert.strictEqual(evalRule('null',    {}), null));

