  for (const seg of segments) {
    if (BLOCKED.has(seg)) return undefined;
    if (cur === null || typeof cur !== 'object') return undefined;
    cur = Object.prototype.hasOwnProperty.call(cur, seg) ? cur[seg] : undefined;
