 *   <, <=, >, >=   — numeric / string comparison
 *   ==, !=         — equality (strict)
 *   in             — field value is one of the elements in `value` (array)
 *   contains       — field value (array or string) contains `value`
 *
 * @param {{ op: string, field: string, value: unknown }} rule
 * @param {Record<string, unknown>} ctx
 * @returns {boolean}
 * @throws {Error} on unsupported operator or malformed input
 */
function evalRule(rule, ctx) {
  if (!rule || typeof rule !== 'object') {
    throw new Error('rule must be a JSON object');
  }

  const { op, field, value } = rule;

  const ALLOWED_OPS = new Set(['<', '<=', '>', '>=', '==', '!=', 'in', 'contains']);
  if (!ALLOWED_OPS.has(op)) {
    throw new Error(
      `Unsupported operator "${op}". Allowed: ${[...ALLOWED_OPS].join(', ')}`
    );
  }

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('"field" must be a non-empty string');
  }

  const fieldValue = getField(ctx, field);

  switch (op) {
    case '<':   return fieldValue <  value;
    case '<=':  return fieldValue <= value;
    case '>':   return fieldValue >  value;
    case '>=':  return fieldValue >= value;
    case '==':  return fieldValue === value;
    case '!=':  return fieldValue !== value;

    case 'in':
      if (!Array.isArray(value)) {
        throw new Error('"value" must be an array when op is "in"');
