// ---------------------------------------------------------------------------
// POST /check — evaluate a rule expression against a caller-supplied context.
//
// NOTE: The RULES_ENGINE.md "reference implementation" uses new Function() /
// eval() to execute arbitrary caller-supplied JavaScript on the server.  That
// is a critical Remote Code Execution vulnerability and has NOT been followed
// here.  Instead, rules are expressed as a simple JSON predicate object and
// evaluated with an explicit, sandboxed evaluator that never calls eval() or
// new Function().
//
// Request body:
//   {
//     "rule": {
//       "op":    "<" | "<=" | ">" | ">=" | "==" | "!=" | "in" | "contains",
//       "field": "<dot-separated path into context>",
//       "value": <any JSON value>
//     },
//     "context": { <arbitrary key/value pairs> }
//   }
//
// Response:
//   { "result": true | false }
//   { "error":  "<message>" }   (400 on bad input)
// ---------------------------------------------------------------------------

/**
 * Resolve a dot-separated field path against an object.
 * Returns `undefined` if any segment is missing.
 *
 * @param {Record<string, unknown>} obj
 * @param {string} path  e.g. "order.amount"
 * @returns {unknown}
 */
function getField(obj, path) {
  if (typeof path !== 'string' || path.trim() === '') return undefined;
  return path.split('.').reduce(
    (current, key) =>
      current !== null && current !== undefined ? current[key] : undefined,
    obj
  );
}

/**
 * Evaluate a single predicate rule against a context object.
 *
 * Supported operators:
 *   <, <=, >, >=   — numeric / string comparison
 *   ==, !=         — equality (strict)
 *   in             — field value is one of the elements in `value` (array)
 *   contains       — field value (array or string) contains `value`
 *
 * @param {{ op: string, field: string, value: unknown }} rule
 * @param {Record<string, unknown>} ctx
 * @returns {boolean}
 * @throws {Error} on unsupported operator or malformed input
 */
function evalRule(rule, ctx) {
  if (!rule || typeof rule !== 'object') {
    throw new Error('rule must be a JSON object');
  }

  const { op, field, value } = rule;

  const ALLOWED_OPS = new Set(['<', '<=', '>', '>=', '==', '!=', 'in', 'contains']);
  if (!ALLOWED_OPS.has(op)) {
    throw new Error(
      `Unsupported operator "${op}". Allowed: ${[...ALLOWED_OPS].join(', ')}`
    );
  }

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('"field" must be a non-empty string');
  }

  const fieldValue = getField(ctx, field);

  switch (op) {
    case '<':   return fieldValue <  value;
    case '<=':  return fieldValue <= value;
    case '>':   return fieldValue >  value;
    case '>=':  return fieldValue >= value;
    case '==':  return fieldValue === value;
    case '!=':  return fieldValue !== value;

    case 'in':
      if (!Array.isArray(value)) {
        throw new Error('"value" must be an array when op is "in"');
      }
      return value.includes(fieldValue);

    case 'contains':
      if (Array.isArray(fieldValue)) return fieldValue.includes(value);
      if (typeof fieldValue === 'string') return fieldValue.includes(String(value));
      throw new Error(
        `"contains" requires the field to be an array or string, got ${typeof fieldValue}`
      );

    default:
      // Unreachable given the allow-list check above, but keeps linters happy.
      throw new Error(`Unsupported operator "${op}"`);
  }
}

