// ---------------------------------------------------------------------------

/**
 * Tokeniser
 *
 * Produces a flat array of tokens from an expression string.
 * Supported token kinds:
 *   NUMBER  — integer or floating-point literal
 *   STRING  — single- or double-quoted string literal
 *   BOOL    — true / false
 *   NULL    — null
 *   IDENT   — identifier (variable or property name)
 *   DOT     — .
 *   OP      — operator (comparison, logical, arithmetic)
 *   LPAREN  — (
 *   RPAREN  — )
 *   EOF     — end of input
 */
function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Number literal
    if (/[0-9]/.test(src[i]) || (src[i] === '-' && /[0-9]/.test(src[i + 1] ?? ''))) {
      let raw = '';
      if (src[i] === '-') raw += src[i++];
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      tokens.push({ kind: 'NUMBER', value: Number(raw) });
      continue;
    }

    // String literal (single or double quoted)
    if (src[i] === '"' || src[i] === "'") {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          i++;
          const esc = src[i++];
          str += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc === 'r' ? '\r' : esc;
        } else {
          str += src[i++];
        }
      }
      if (src[i] !== quote) throw new EvalError(`Unterminated string literal`);
      i++; // consume closing quote
      tokens.push({ kind: 'STRING', value: str });
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) name += src[i++];
      if (name === 'true')  { tokens.push({ kind: 'BOOL',  value: true  }); continue; }
      if (name === 'false') { tokens.push({ kind: 'BOOL',  value: false }); continue; }
      if (name === 'null')  { tokens.push({ kind: 'NULL',  value: null  }); continue; }
      if (name === 'and')   { tokens.push({ kind: 'OP',    value: '&&'  }); continue; }
      if (name === 'or')    { tokens.push({ kind: 'OP',    value: '||'  }); continue; }
      if (name === 'not')   { tokens.push({ kind: 'OP',    value: '!'   }); continue; }
      tokens.push({ kind: 'IDENT', value: name });
      continue;
    }

    // Two-character operators (must be checked before single-char)
    const two = src.slice(i, i + 2);
    if (['===', '!==', '==', '!=', '<=', '>=', '&&', '||'].includes(two) ||
        src.slice(i, i + 3) === '===') {
      const three = src.slice(i, i + 3);
      if (three === '===' || three === '!==') {
        tokens.push({ kind: 'OP', value: three }); i += 3; continue;
      }
      tokens.push({ kind: 'OP', value: two }); i += 2; continue;
    }

    // Single-character tokens
    const ch = src[i];
    if (ch === '.')  { tokens.push({ kind: 'DOT',    value: '.' }); i++; continue; }
    if (ch === '(')  { tokens.push({ kind: 'LPAREN', value: '(' }); i++; continue; }
    if (ch === ')')  { tokens.push({ kind: 'RPAREN', value: ')' }); i++; continue; }
    if (ch === '!')  { tokens.push({ kind: 'OP',     value: '!' }); i++; continue; }
