    case 'Logical': {
      // Short-circuit evaluation
      const lv = evaluate(node.left, ctx);
      if (node.op === '&&') return lv ? evaluate(node.right, ctx) : lv;
      if (node.op === '||') return lv ? lv : evaluate(node.right, ctx);
