      let raw = '';
      if (src[i] === '-') raw += src[i++];
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      tokens.push({ kind: 'NUMBER', value: Number(raw) });
      continue;
    }

    // String literal (single or double quoted)
    if (src[i] === '"' || src[i] === "'") {
