        if (src[i] === '\\') {
          i++;
          const esc = src[i++];
          str += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc === 'r' ? '\r' : esc;
        } else {
          str += src[i++];
        }
      }
      if (src[i] !== quote) throw new EvalError(`Unterminated string literal`);
      i++; // consume closing quote
      tokens.push({ kind: 'STRING', value: str });
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) name += src[i++];
      if (name === 'true')  { tokens.push({ kind: 'BOOL',  value: true  }); continue; }
      if (name === 'false') { tokens.push({ kind: 'BOOL',  value: false }); continue; }
      if (name === 'null')  { tokens.push({ kind: 'NULL',  value: null  }); continue; }
      if (name === 'and')   { tokens.push({ kind: 'OP',    value: '&&'  }); continue; }
      if (name === 'or')    { tokens.push({ kind: 'OP',    value: '||'  }); continue; }
      if (name === 'not')   { tokens.push({ kind: 'OP',    value: '!'   }); continue; }
      tokens.push({ kind: 'IDENT', value: name });
