import express from "express";

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports a purposefully-limited expression language that covers the stated
// use-cases (field comparisons, logical connectives) without ever passing
// caller-supplied strings to eval() or new Function().
//
// Supported grammar (recursive):
//
//   expr   := unary ( logical unary )*
//   unary  := "!" unary | atom
//   atom   := "(" expr ")" | comparison | boolLiteral
//
//   comparison := operand compOp operand
//   compOp     := "===" | "!==" | "==" | "!=" | ">=" | "<=" | ">" | "<"
//
//   logical    := "&&" | "||"
//
//   operand    := numberLiteral | stringLiteral | boolLiteral
//               | nullLiteral | fieldPath
//
//   fieldPath  := identifier ( "." identifier )*   — resolved against ctx
//
// Examples:
//   ctx.amount > 100
//   ctx.role === "admin" && ctx.active !== false
//   !(ctx.score < 50) || ctx.override === true
// ---------------------------------------------------------------------------

class RuleEvaluationError extends Error {
  constructor(message) {
    super(message);
    this.name = "RuleEvaluationError";
  }
}

// -- Tokeniser ---------------------------------------------------------------

const TOKEN = Object.freeze({
  NUMBER:  "NUMBER",
  STRING:  "STRING",
  BOOL:    "BOOL",
  NULL:    "NULL",
  IDENT:   "IDENT",
  DOT:     "DOT",
  LPAREN:  "LPAREN",
  RPAREN:  "RPAREN",
  BANG:    "BANG",
  COMPARE: "COMPARE",
  LOGICAL: "LOGICAL",
  EOF:     "EOF",
});

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Two/three-char operators first
    const threeChar = src.slice(i, i + 3);
    const twoChar   = src.slice(i, i + 2);

    if (["===", "!=="].includes(threeChar)) {
      tokens.push({ type: TOKEN.COMPARE, value: threeChar }); i += 3; continue;
    }
    if (["==", "!=", ">=", "<=", "&&", "||"].includes(twoChar)) {
      const type = (twoChar === "&&" || twoChar === "||") ? TOKEN.LOGICAL : TOKEN.COMPARE;
      tokens.push({ type, value: twoChar }); i += 2; continue;
    }

    const ch = src[i];

    if (ch === ">") { tokens.push({ type: TOKEN.COMPARE, value: ">" });  i++; continue; }
    if (ch === "<") { tokens.push({ type: TOKEN.COMPARE, value: "<" });  i++; continue; }
    if (ch === "!") { tokens.push({ type: TOKEN.BANG,    value: "!" });  i++; continue; }
    if (ch === "(") { tokens.push({ type: TOKEN.LPAREN,  value: "(" });  i++; continue; }
    if (ch === ")") { tokens.push({ type: TOKEN.RPAREN,  value: ")" });  i++; continue; }
    if (ch === ".") { tokens.push({ type: TOKEN.DOT,     value: "." });  i++; continue; }

    // Number literal
    if (/[0-9]/.test(ch) || (ch === "-" && /[0-9]/.test(src[i + 1] ?? ""))) {
      let num = ch; i++;
      while (i < src.length && /[0-9.]/.test(src[i])) { num += src[i]; i++; }
      tokens.push({ type: TOKEN.NUMBER, value: Number(num) }); continue;
    }

    // String literal (single or double quotes, no escape sequences needed)
    if (ch === '"' || ch === "'") {
      const quote = ch; i++;
      let str = "";
      while (i < src.length && src[i] !== quote) {
        if (src[i] === "\\" && i + 1 < src.length) { i++; str += src[i]; }
        else { str += src[i]; }
        i++;
      }
      if (src[i] !== quote) throw new RuleEvaluationError("Unterminated string literal");
      i++; // closing quote
      tokens.push({ type: TOKEN.STRING, value: str }); continue;
    }

    // Identifier / keyword
    if (/[a-zA-Z_$]/.test(ch)) {
      let id = ""; 
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) { id += src[i]; i++; }
      if (id === "true" || id === "false") {
        tokens.push({ type: TOKEN.BOOL, value: id === "true" });
      } else if (id === "null") {
        tokens.push({ type: TOKEN.NULL, value: null });
      } else {
        tokens.push({ type: TOKEN.IDENT, value: id });
      }
      continue;
    }

    throw new RuleEvaluationError(`Unexpected character: '${ch}'`);
  }

  tokens.push({ type: TOKEN.EOF, value: null });
  return tokens;
}

// -- Parser / evaluator (recursive descent) ----------------------------------

function createParser(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type) {
    const tok = consume();
    if (tok.type !== type) {
      throw new RuleEvaluationError(`Expected ${type}, got ${tok.type} ('${tok.value}')`);
    }
    return tok;
  }

  // Resolve a dotted path like "ctx.order.amount" against the context object.
  function resolvePath(parts) {
    let value = ctx;
    for (const part of parts) {
      if (value === null || value === undefined) return undefined;
      if (typeof value !== "object") {
        throw new RuleEvaluationError(
          `Cannot read property '${part}' of ${JSON.stringify(value)}`
        );
      }
      value = value[part];
    }
    return value;
  }

  // operand := number | string | bool | null | fieldPath
  function parseOperand() {
    const tok = peek();

    if (tok.type === TOKEN.NUMBER) { consume(); return tok.value; }
    if (tok.type === TOKEN.STRING) { consume(); return tok.value; }
    if (tok.type === TOKEN.BOOL)   { consume(); return tok.value; }
    if (tok.type === TOKEN.NULL)   { consume(); return null; }

    if (tok.type === TOKEN.IDENT) {
      // Collect a dotted identifier path
      const parts = [];
      parts.push(consume().value);
      while (peek().type === TOKEN.DOT) {
        consume(); // eat "."
        parts.push(expect(TOKEN.IDENT).value);
      }
      return resolvePath(parts);
    }

    throw new RuleEvaluationError(`Unexpected token '${tok.value}' (${tok.type})`);
  }

  // comparison := operand compOp operand  |  operand
  function parseComparison() {
    const left = parseOperand();

    if (peek().type !== TOKEN.COMPARE) return left;

    const op    = consume().value;
    const right = parseOperand();

    switch (op) {
      case "===": return left === right;
      case "!==": return left !== right;
      case "==":  return left == right;   // eslint-disable-line eqeqeq
      case "!=":  return left != right;   // eslint-disable-line eqeqeq
      case ">=":  return left >= right;
      case "<=":  return left <= right;
      case ">":   return left >  right;
      case "<":   return left <  right;
      default:    throw new RuleEvaluationError(`Unknown operator: ${op}`);
    }
  }

  // unary := "!" unary | atom
  function parseUnary() {
    if (peek().type === TOKEN.BANG) {
      consume();
      return !parseUnary();
    }
    return parseAtom();
  }

  // atom := "(" expr ")" | comparison
  function parseAtom() {
    if (peek().type === TOKEN.LPAREN) {
      consume(); // eat "("
      const value = parseExpr();
      expect(TOKEN.RPAREN);
      return value;
    }
    return parseComparison();
  }

  // expr := unary ( logical unary )*
  function parseExpr() {
    let left = parseUnary();

    while (peek().type === TOKEN.LOGICAL) {
      const op = consume().value;
      // Short-circuit evaluation
      if (op === "&&") {
        const right = parseUnary();
        left = left && right;
      } else {
        const right = parseUnary();
        left = left || right;
      }
    }

    return left;
  }

  return { parseExpr, peek };
}

/**
 * Safely evaluate a rule expression string against a context object.
 *
 * @param {string} expr - Rule expression, e.g. 'ctx.amount > 100'
 * @param {object} ctx  - Context object made available as the root scope
 * @returns {boolean}
 */
function evalRule(expr, ctx) {
  if (typeof expr !== "string" || expr.trim() === "") {
    throw new RuleEvaluationError("'rule' must be a non-empty string");
  }

  const tokens = tokenise(expr.trim());

  // Wrap the context so expressions can use "ctx.field" just like the docs show.
  const rootCtx = { ctx };

  const parser = createParser(tokens, rootCtx);
  const result = parser.parseExpr();

  if (parser.peek().type !== TOKEN.EOF) {
    throw new RuleEvaluationError(
      `Unexpected token '${parser.peek().value}' — expression not fully consumed`
    );
  }

  return Boolean(result);
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * POST /check
 *
 * Body (JSON):
 *   {
 *     "rule":    "<expression>",   // required — e.g. "ctx.amount > 100"
 *     "context": { ... }           // required — data the rule is evaluated against
 *   }
 *
 * Response 200:
 *   { "result": true | false }
 *
 * Response 400:
 *   { "error": "<message>" }
 */
app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== "string" || rule.trim() === "") {
    return res
      .status(400)
      .json({ error: "'rule' is required and must be a non-empty string" });
  }

  if (context === undefined || context === null || typeof context !== "object") {
    return res
      .status(400)
      .json({ error: "'context' is required and must be an object" });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    if (err instanceof RuleEvaluationError) {
      return res.status(400).json({ error: err.message });
    }
    // Unexpected internal error — don't leak details
    console.error("Unexpected error in /check:", err);
    return res.status(500).json({ error: "Internal server error" });
  }
});

export default app;

