  const peek=()=>tokens[pos];
  const consume=()=>tokens[pos++];
  function expect(type){const tok=consume();if(tok.type!==type)throw new RuleEvaluationError(`Expected ${type}, got ${tok.type}`);return tok;}
  function resolvePath(parts){
    let value=ctx;
    for(const part of parts){
      if(value===null||value===undefined)return undefined;
      if(typeof value!=="object")throw new RuleEvaluationError(`Cannot read '${part}'`);
      value=value[part];
    }
    return value;
  }
  function parseOperand(){
    const tok=peek();
    if(tok.type===TOKEN.NUMBER){consume();return tok.value;}
    if(tok.type===TOKEN.STRING){consume();return tok.value;}
    if(tok.type===TOKEN.BOOL){consume();return tok.value;}
    if(tok.type===TOKEN.NULL){consume();return null;}
    if(tok.type===TOKEN.IDENT){
      const parts=[];parts.push(consume().value);
      while(peek().type===TOKEN.DOT){consume();parts.push(expect(TOKEN.IDENT).value);}
      return resolvePath(parts);
    }
    throw new RuleEvaluationError(`Unexpected token '${tok.value}'`);
  }
  function parseComparison(){
    const left=parseOperand();
    if(peek().type!==TOKEN.COMPARE)return left;
    const op=consume().value, right=parseOperand();
    switch(op){
      case"===":return left===right; case"!==":return left!==right;
      case"==":return left==right;   case"!=":return left!=right;
      case">=":return left>=right;   case"<=":return left<=right;
      case">":return left>right;     case"<":return left<right;
      default:throw new RuleEvaluationError(`Unknown operator: ${op}`);
    }
  }
  function parseUnary(){if(peek().type===TOKEN.BANG){consume();return !parseUnary();}return parseAtom();}
  function parseAtom(){
    if(peek().type===TOKEN.LPAREN){consume();const v=parseExpr();expect(TOKEN.RPAREN);return v;}
    return parseComparison();
  }
  function parseExpr(){
    let left=parseUnary();
    while(peek().type===TOKEN.LOGICAL){
      const op=consume().value;
      const right=parseUnary();
      left=op==="&&"?left&&right:left||right;
    }
    return left;
  }
  return {parseExpr, peek};
}

function evalRule(expr, ctx) {
  if(typeof expr!=="string"||expr.trim()==="")throw new RuleEvaluationError("'rule' must be a non-empty string");
  const tokens=tokenise(expr.trim());
  const rootCtx={ctx};
  const parser=createParser(tokens,rootCtx);
  const result=parser.parseExpr();
  if(parser.peek().type!==TOKEN.EOF)throw new RuleEvaluationError(`Unexpected token '${parser.peek().value}'`);
  return Boolean(result);
}

// ── Tests ────────────────────────────────────────────────────────────────────

let passed = 0, failed = 0;

function test(label, expr, ctx, expected) {
  let result;
  try {
    result = evalRule(expr, ctx);
  } catch(e) {
    result = `ERROR: ${e.message}`;
  }
  const ok = result === expected;
  console.log(`${ok ? "✅" : "❌"} ${label}`);
  if (!ok) console.log(`     expr:     ${expr}\n     context:  ${JSON.stringify(ctx)}\n     expected: ${expected}\n     got:      ${result}`);
  ok ? passed++ : failed++;
}

function testThrows(label, expr, ctx) {
  try {
    evalRule(expr, ctx);
    console.log(`❌ ${label}  (expected an error but got none)`);
    failed++;
  } catch(e) {
    if (e instanceof RuleEvaluationError) {
      console.log(`✅ ${label}  → ${e.message}`);
      passed++;
    } else {
      console.log(`❌ ${label}  (wrong error type: ${e.constructor.name})`);
      failed++;
    }
  }
}

// Basic comparisons (doc example)
test("amount > 100  (true)",  "ctx.amount > 100",  { amount: 150 }, true);
test("amount > 100  (false)", "ctx.amount > 100",  { amount: 50  }, false);
test("amount >= 100 (equal)", "ctx.amount >= 100", { amount: 100 }, true);
test("amount <= 99  (true)",  "ctx.amount <= 99",  { amount: 99  }, true);
test("amount < 99   (false)", "ctx.amount < 99",   { amount: 99  }, false);

// String comparisons
test('role === "admin"  (true)',  'ctx.role === "admin"', { role: "admin" }, true);
test('role === "admin"  (false)', 'ctx.role === "admin"', { role: "user"  }, false);
test("role !== \"admin\" (true)", 'ctx.role !== "admin"', { role: "user"  }, true);

// Boolean / null
test("active === true  (true)",  "ctx.active === true",  { active: true  }, true);
test("active === false (true)",  "ctx.active === false", { active: false }, true);
test("value === null   (true)",  "ctx.value === null",   { value: null   }, true);
test("value === null   (false)", "ctx.value === null",   { value: 1      }, false);

// Logical AND
test("amount > 100 && role === \"admin\"  (both true)",
  'ctx.amount > 100 && ctx.role === "admin"',
  { amount: 200, role: "admin" }, true);
test("amount > 100 && role === \"admin\"  (one false)",
  'ctx.amount > 100 && ctx.role === "admin"',
  { amount: 50,  role: "admin" }, false);

// Logical OR
test('score >= 90 || override === true  (first branch)',
  "ctx.score >= 90 || ctx.override === true",
  { score: 95,  override: false }, true);
test('score >= 90 || override === true  (second branch)',
  "ctx.score >= 90 || ctx.override === true",
  { score: 50,  override: true  }, true);
test('score >= 90 || override === true  (both false)',
  "ctx.score >= 90 || ctx.override === true",
  { score: 50,  override: false }, false);

// Negation (!)
test("!(ctx.score < 50) → true",  "!(ctx.score < 50)", { score: 80 }, true);
test("!(ctx.score < 50) → false", "!(ctx.score < 50)", { score: 30 }, false);

// Grouped parentheses
test("(ctx.a > 1 || ctx.b > 1) && ctx.c === true  (true)",
  "(ctx.a > 1 || ctx.b > 1) && ctx.c === true",
  { a: 0, b: 5, c: true }, true);
test("(ctx.a > 1 || ctx.b > 1) && ctx.c === true  (false — c)",
  "(ctx.a > 1 || ctx.b > 1) && ctx.c === true",
  { a: 0, b: 5, c: false }, false);

// Deeply nested path
test("ctx.order.amount > 50  (true)",  "ctx.order.amount > 50", { order: { amount: 99 } }, true);
test("ctx.order.amount > 50  (false)", "ctx.order.amount > 50", { order: { amount: 10 } }, false);

// RCE payloads must be rejected as parse errors, not executed
testThrows("RCE: process.exit(1)",              "process.exit(1)",                           {});
testThrows("RCE: require(...)",                 "require('child_process')",                  {});
testThrows("RCE: constructor trick",            "constructor.constructor('return 1')()",     {});
testThrows("RCE: __proto__",                    "__proto__.polluted === true",               {});
testThrows("RCE: function call syntax",         "ctx.amount > foo()",                        { amount: 1 });
testThrows("Bad rule: empty string",            "",                                          {});
testThrows("Bad rule: unterminated string",     "ctx.role === \"admin",                      { role: "admin" });
testThrows("Bad rule: missing closing paren",   "(ctx.a > 1",                                { a: 5 });

// == / != (loose equality) supported
test("ctx.x == 1  (loose, string '1')", "ctx.x == 1", { x: "1" }, true);
test("ctx.x != 2  (loose, string '1')", "ctx.x != 2", { x: "1" }, true);

console.log(`\n${passed + failed} tests: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
EOF

