// Blocked property names that must never be traversed — accessing them could
// expose prototype-chain internals or enable prototype-pollution reads.
const FORBIDDEN_KEYS = new Set(["__proto__", "prototype", "constructor"]);

// Resolve a dotted path like "ctx.order.amount" against the context object.
function resolvePath(parts) {
  let value = ctx;
  for (const part of parts) {
    if (FORBIDDEN_KEYS.has(part)) {
      throw new RuleEvaluationError(`Property '${part}' is not allowed in rule expressions`);
    }
    if (value === null || value === undefined) return undefined;
    if (typeof value !== "object") {
      throw new RuleEvaluationError(
        `Cannot read property '${part}' of ${JSON.stringify(value)}`
      );
    }
    value = Object.prototype.hasOwnProperty.call(value, part) ? value[part] : undefined;
  }
  return value;
}

