import express from "express";

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Supports a purposefully-limited expression language that covers the stated
// use-cases (field comparisons, logical connectives) without ever passing
// caller-supplied strings to eval() or new Function().
//
// Supported grammar (recursive):
//
//   expr   := unary ( logical unary )*
//   unary  := "!" unary | atom
//   atom   := "(" expr ")" | comparison | boolLiteral
//
//   comparison := operand compOp operand
//   compOp     := "===" | "!==" | "==" | "!=" | ">=" | "<=" | ">" | "<"
//
//   logical    := "&&" | "||"
//
//   operand    := numberLiteral | stringLiteral | boolLiteral
//               | nullLiteral | fieldPath
//
//   fieldPath  := identifier ( "." identifier )*   — resolved against ctx
//
// Examples:
//   ctx.amount > 100
//   ctx.role === "admin" && ctx.active !== false
//   !(ctx.score < 50) || ctx.override === true
// ---------------------------------------------------------------------------

class RuleEvaluationError extends Error {
  constructor(message) {
    super(message);
    this.name = "RuleEvaluationError";
  }
}

// -- Tokeniser ---------------------------------------------------------------

const TOKEN = Object.freeze({
  NUMBER:  "NUMBER",
  STRING:  "STRING",
  BOOL:    "BOOL",
  NULL:    "NULL",
  IDENT:   "IDENT",
  DOT:     "DOT",
  LPAREN:  "LPAREN",
  RPAREN:  "RPAREN",
  BANG:    "BANG",
  COMPARE: "COMPARE",
  LOGICAL: "LOGICAL",
  EOF:     "EOF",
});

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Skip whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Two/three-char operators first
    const threeChar = src.slice(i, i + 3);
    const twoChar   = src.slice(i, i + 2);

    if (["===", "!=="].includes(threeChar)) {
      tokens.push({ type: TOKEN.COMPARE, value: threeChar }); i += 3; continue;
    }
    if (["==", "!=", ">=", "<=", "&&", "||"].includes(twoChar)) {
      const type = (twoChar === "&&" || twoChar === "||") ? TOKEN.LOGICAL : TOKEN.COMPARE;
      tokens.push({ type, value: twoChar }); i += 2; continue;
    }

    const ch = src[i];

    if (ch === ">") { tokens.push({ type: TOKEN.COMPARE, value: ">" });  i++; continue; }
    if (ch === "<") { tokens.push({ type: TOKEN.COMPARE, value: "<" });  i++; continue; }
    if (ch === "!") { tokens.push({ type: TOKEN.BANG,    value: "!" });  i++; continue; }
    if (ch === "(") { tokens.push({ type: TOKEN.LPAREN,  value: "(" });  i++; continue; }
    if (ch === ")") { tokens.push({ type: TOKEN.RPAREN,  value: ")" });  i++; continue; }
    if (ch === ".") { tokens.push({ type: TOKEN.DOT,     value: "." });  i++; continue; }

    // Number literal
    if (/[0-9]/.test(ch) || (ch === "-" && /[0-9]/.test(src[i + 1] ?? ""))) {
      let num = ch; i++;
      while (i < src.length && /[0-9.]/.test(src[i])) { num += src[i]; i++; }
      tokens.push({ type: TOKEN.NUMBER, value: Number(num) }); continue;
    }

    // String literal (single or double quotes, no escape sequences needed)
    if (ch === '"' || ch === "'") {
      const quote = ch; i++;
      let str = "";
      while (i < src.length && src[i] !== quote) {
        if (src[i] === "\\" && i + 1 < src.length) { i++; str += src[i]; }
        else { str += src[i]; }
        i++;
      }
      if (src[i] !== quote) throw new RuleEvaluationError("Unterminated string literal");
      i++; // closing quote
      tokens.push({ type: TOKEN.STRING, value: str }); continue;
    }

    // Identifier / keyword
    if (/[a-zA-Z_$]/.test(ch)) {
      let id = ""; 
      while (i < src.length && /[a-zA-Z0-9_$]/.test(src[i])) { id += src[i]; i++; }
      if (id === "true" || id === "false") {
        tokens.push({ type: TOKEN.BOOL, value: id === "true" });
      } else if (id === "null") {
        tokens.push({ type: TOKEN.NULL, value: null });
      } else {
        tokens.push({ type: TOKEN.IDENT, value: id });
      }
      continue;
    }

    throw new RuleEvaluationError(`Unexpected character: '${ch}'`);
  }

  tokens.push({ type: TOKEN.EOF, value: null });
  return tokens;
}

// -- Parser / evaluator (recursive descent) ----------------------------------

function createParser(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type) {
    const tok = consume();
    if (tok.type !== type) {
      throw new RuleEvaluationError(`Expected ${type}, got ${tok.type} ('${tok.value}')`);
    }
    return tok;
  }

  // Blocked property names that must never be traversed — accessing them could
