 *   rule  = field op literal
 *          | field
 *   field   = /[a-zA-Z_][a-zA-Z0-9_.]+/   (dot-notation, must start with ctx)
 *   op      = '===' | '==' | '!==' | '!=' | '>=' | '<=' | '>' | '<'
 *   literal = number | 'true' | 'false' | "'" string "'" | '"' string '"'
 */
function parseRule(rule) {
  if (typeof rule !== 'string') throw new Error('"rule" must be a string');

  const ruleStr = rule.trim();

