  // Operators are tried longest-first to avoid '==' shadowing '==='.
  const BINARY_RE =
    /^([a-zA-Z_][a-zA-Z0-9_.]*)\s*(===|!==|==|!=|>=|<=|>|<)\s*(true|false|-?[0-9]+(?:\.[0-9]+)?|"[^"]*"|'[^']*')$/;

  const binaryMatch = BINARY_RE.exec(ruleStr);
  if (binaryMatch) {
    const [, left, op, rawRight] = binaryMatch;
    return { left, op, right: rawRight };
  }

  // Boolean field check: just a field path
  const BOOL_RE = /^([a-zA-Z_][a-zA-Z0-9_.]*)$/;
  const boolMatch = BOOL_RE.exec(ruleStr);
