const ALLOWED_OPS = {
  eq:         (a, b) => a === b,
  neq:        (a, b) => a !== b,
  gt:         (a, b) => a > b,
  gte:        (a, b) => a >= b,
  lt:         (a, b) => a < b,
  lte:        (a, b) => a <= b,
  contains:   (a, b) => typeof a === 'string' && a.includes(b),
  startsWith: (a, b) => typeof a === 'string' && a.startsWith(b),
  endsWith:   (a, b) => typeof a === 'string' && a.endsWith(b),
};

function safeGet(context, field) {
  if (typeof field !== 'string') return undefined;
  if (!Object.prototype.hasOwnProperty.call(context, field)) return undefined;
  return context[field];
}

function evalRule(context, rule) {
  const { field, op, value } = rule;
  if (typeof field !== 'string' || field.trim() === '') throw new Error('rule.field must be a non-empty string');
  if (!Object.prototype.hasOwnProperty.call(ALLOWED_OPS, op)) throw new Error('unsupported op');
  if (value === undefined) throw new Error('rule.value is required');
  const fieldValue = safeGet(context, field);
  return ALLOWED_OPS[op](fieldValue, value);
}

